def _algo_regime(key: str) -> str:
    k = (key or "").lower()
    if k in _NAMED_REGIME:
        return _NAMED_REGIME[k]
    m = re.match(r"^a1_(\d+)$", k)
    if m:
        return _A1_REGIME.get(int(m.group(1)), "live")
    m = re.match(r"^a2_(\d+)$", k)
    if m:
        return _A2_REGIME.get(int(m.group(1)), "live")
    return "live"


