# yeni defter eklenince takma adı kendiliğinden gelir.
_ALGO_SHORT_ALIASES: dict[str, str] = {}
for _bk in _ALGO_ISLEMLER_KEYS:
    _sq = _squash_book_id(_OVERVIEW_SHORT_LABELS.get(_bk, ""))
    if _sq and _sq not in _ALGO_SHORT_ALIASES:
        _ALGO_SHORT_ALIASES[_sq] = _bk


def _normalize_algo_book_id(book_id: str) -> str:
    """URL/API book_id → dahili defter anahtarı (eski analiz6_v4 → melez)."""
    key = book_id.lower().strip()
    try:
        sys.path.insert(0, _DIR_POLY)
        from vote_paper import normalize_top_key
        top = normalize_top_key(key)
        if top:
            return top
    except Exception:
        pass
    if re.match(r"^\d+$", key):
        key = f"a2_{int(key):02d}"
    key = _ALGO_BOOK_ALIASES.get(key, key)
    if key not in _ALGO_ISLEMLER_KEYS:
        key = _ALGO_SHORT_ALIASES.get(_squash_book_id(key), key)
    return key


def _load_trader_open_positions(key: str) -> list[dict]:
    """State'teki açık pozisyonları harita/geçmiş için normalize eder."""
    spath = _trader_state_path(key)
    if not os.path.exists(spath):
        return []
    try:
        with open(spath, encoding="utf-8") as f:
            state = json.load(f)
    except Exception:
        return []
    allowed = set(_allowed_syms_for(key))
    out: list[dict] = []
    for p in state.get("open_positions") or []:
        sym = (p.get("symbol") or "").replace("USDT", "")
        if sym and sym not in allowed:
            continue
        out.append({
            "symbol": p.get("symbol"),
            "predicted_dir": p.get("predicted_dir"),
            "entry_hour_tr": p.get("entry_hour_tr"),
            "entry_dow": p.get("entry_dow"),
            "entry_price": p.get("entry_price"),
            "entry_time_tr": p.get("entry_time_tr"),
            "pm_spent": p.get("pm_spent") or p.get("amount"),
            "amount": p.get("amount"),
            "win": None,
            "pnl": 0,
            "open": True,
        })
    return out


def _enrich_entry_time_fields(t: dict) -> dict:
    if t.get("entry_dow") is not None and t.get("entry_hour_tr") is not None:
        return t
    out = dict(t)
    ts = out.get("entry_time_tr") or out.get("exit_time_tr")
    if ts:
        try:
            dt = datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=_TZ_TR)
            else:
                dt = dt.astimezone(_TZ_TR)
            if out.get("entry_dow") is None:
                out["entry_dow"] = dt.weekday()
            if out.get("entry_hour_tr") is None:
                out["entry_hour_tr"] = dt.hour
        except (ValueError, TypeError):
            pass
    elif out.get("entry_hour_tr") is None:
        m = re.match(r"(\d{1,2}):", out.get("hour_label", ""))
        if m:
            out["entry_hour_tr"] = int(m.group(1))
    return out


_HIST_JSON_CACHE: dict[str, tuple[float, int, list]] = {}


def _read_history_json(path: str) -> list:
    """mtime cache — /poly yenilemesi onlarca history dosyasını tekrar okumasın."""
    try:
        st = os.stat(path)
    except OSError:
        return []
    hit = _HIST_JSON_CACHE.get(path)
    if hit and hit[0] == st.st_mtime and hit[1] == st.st_size:
        return hit[2]
    try:
        with open(path, encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, list):
            raw = []
    except Exception:
        return []
    hist = [_enrich_entry_time_fields(t) for t in raw if isinstance(t, dict)]
    _HIST_JSON_CACHE[path] = (st.st_mtime, st.st_size, hist)
    return hist


def _load_trader_history(key: str, slot: int | None = None) -> list:
    path = _trader_history_path(key, slot)
    if not os.path.exists(path):
        return []
    return _filter_hist_for(key, list(_read_history_json(path)))


def _auto_label(key: str) -> str:
    if key in _ANALYSIS_LABELS:
        return _ANALYSIS_LABELS[key]
    m = re.match(r"^analiz(\d+)$", key)
    if m:
        return f"{m.group(1)}. Analiz"
    if key.startswith("5m_btc_"):
        n = key.replace("5m_btc_", "")
        if n == "real":
            return "5M 201 BTC"
        return f"5M {n.upper()} BTC"
    return key.replace("_", " ").title()


def _build_system_list(order: list[str], *, include_live: bool = False) -> list[tuple[str, str]]:
    on_disk = _discover_trader_keys()
    seen: set[str] = set()
    out: list[tuple[str, str]] = []
    live_skip = frozenset() if include_live else _LIVE_PM_ANALYSES
    for key in order:
        if key in _REMOVED_ANALYSES or key in live_skip:
            continue
        if not _trader_exists(key, on_disk) and key not in _ANALYSIS_LABELS:
            continue
        out.append((key, _ANALYSIS_LABELS.get(key, _auto_label(key))))
        seen.add(key)
    for key in sorted(on_disk - seen):
        if key in _REMOVED_ANALYSES or key in live_skip:
            continue
        out.append((key, _ANALYSIS_LABELS.get(key, _auto_label(key))))
    return out


def _build_harita_tabs() -> list[tuple[str, str]]:
    on_disk = _discover_trader_keys()
    merged_extra = {k for extras in _HEATMAP_MERGE.values() for k in extras}
    skip_tabs = _REMOVED_ANALYSES | _ALGO_STATS_EXCLUDE | frozenset({"manual"}) | merged_extra
    out: list[tuple[str, str]] = []
    seen: set[str] = set()
    for key in _HEATMAP_ORDER:
        if key in _REMOVED_ANALYSES or key in _LIVE_PM_ANALYSES:
            continue
        if not _trader_exists(key, on_disk) and key not in _ANALYSIS_LABELS:
            continue
        out.append((key, _ANALYSIS_LABELS.get(key, _auto_label(key))))
        seen.add(key)
    for key in sorted(on_disk - seen):
        if key in skip_tabs:
            continue
        out.append((key, _ANALYSIS_LABELS.get(key, _auto_label(key))))
    return out


def _heatmap_history_keys(key: str) -> list[str]:
    keys = [key]
    for extra in _HEATMAP_MERGE.get(key, []):
        if extra not in keys:
            keys.append(extra)
    return keys


def _load_heatmap_history(key: str) -> list:
    """Harita API — birleşik kaynaklar + sembol filtresi."""
    allowed = set(_allowed_syms_for(key))
    hist: list = []
    for k in _heatmap_history_keys(key):
        for row in _read_history_json(_trader_history_path(k)):
            sym = row.get("symbol", "").replace("USDT", "")
            if sym in allowed:
                hist.append(row)
    return hist


