_PM_HOME_DISPLAY_DEFAULT = "a2_05"
_PM_HOME_DISPLAY_FILE = os.path.join(_DIR_POLY, "pm_home_display.json")


def _load_pm_home_display() -> dict:
    try:
        with open(_PM_HOME_DISPLAY_FILE, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_pm_home_display(data: dict) -> dict:
    tmp = _PM_HOME_DISPLAY_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    os.replace(tmp, _PM_HOME_DISPLAY_FILE)
    return data


def get_pm_home_display_key() -> str:
    raw = str(_load_pm_home_display().get("book_key") or _PM_HOME_DISPLAY_DEFAULT)
    key = _normalize_algo_book_id(raw)
    if key not in _ALGO_ISLEMLER_KEYS:
        return _PM_HOME_DISPLAY_DEFAULT
    return key


def get_pm_home_display_label(key: str | None = None) -> str:
    k = key or get_pm_home_display_key()
    return _ANALYSIS_LABELS.get(k, k)


def get_pm_home_display_init_bal(key: str | None = None) -> float:
    k = key or get_pm_home_display_key()
    return float(_OVERVIEW_INIT_BAL.get(k, 300) or 300)


def set_pm_home_display_book(key: str, *, source: str = "dashboard") -> dict:
    norm = _normalize_algo_book_id(key)
    if norm not in _ALGO_ISLEMLER_KEYS:
        raise ValueError("geçersiz defter")
    data = {
        "book_key": norm,
        "label": get_pm_home_display_label(norm),
        "updated_at_tr": datetime.now(_TZ_TR).isoformat(),
        "updated_by": source,
    }
    _save_pm_home_display(data)
    return data


def _home_display_ctx() -> tuple[str, str, int, float]:
    """Anasayfa defteri + en iyi dilim (:02/:05/:07)."""
    key = get_pm_home_display_key()
    slot = _best_slot_for_book(key)
    return key, get_pm_home_display_label(key), int(slot), get_pm_home_display_init_bal(key)


def _home_display_hist(key: str, slot: int, state: dict) -> list[dict]:
    """WR/P&L yalnız sıfırlama damgasından sonrası — kartla aynı skor."""
    hist = _load_trader_history(key, slot)
    reset_at = state.get("balance_reset_at_tr")
    if not reset_at:
        return hist
    return [t for t in hist if (t.get("exit_time_tr") or "") >= reset_at]


def _format_display_pm_trade(t: dict, label: str) -> dict | None:
    """Sanal PM kaydı → anasayfa işlem geçmişi satırı."""
    if t.get("win") is None:
        return None
    exit_tr = t.get("exit_time_tr") or t.get("entry_time_tr") or ""
    if not exit_tr:
        return None
    spent = float(t.get("pm_spent") or t.get("amount") or 0)
    pnl_val = t.get("pnl")
    if pnl_val is None:
        return None
    time_s = str(exit_tr)
    if "T" in time_s and len(time_s) >= 16:
        time_s = time_s[11:16]
    elif len(time_s) >= 5:
        time_s = time_s[-5:]
    return {
        "sym": (t.get("symbol") or "").replace("USDT", "") or "?",
        "dir": t.get("predicted_dir") or t.get("pm_token_dir") or "?",
        "spent": round(spent, 2),
        "pnl": round(float(pnl_val), 2),
        "win": bool(t.get("win")),
        "time": time_s,
        "analiz": label,
        "pending": False,
    }


def _format_display_pm_open(pos: dict, label: str) -> dict:
    """Açık sanal pozisyon → Son İşlemler bekleyen satırı."""
    spent = float(pos.get("pm_spent") or pos.get("amount") or 0)
    et = str(pos.get("entry_time_tr") or "")
    time_s = et[11:16] if "T" in et and len(et) >= 16 else et[-5:] if et else ""
    return {
        "sym": (pos.get("symbol") or "").replace("USDT", "") or "?",
        "dir": pos.get("predicted_dir") or pos.get("pm_token_dir") or "?",
        "spent": round(spent, 2),
        "pnl": 0.0,
        "win": None,
        "time": time_s,
        "analiz": label,
        "pending": True,
    }


def _collect_display_pm_positions() -> list[dict]:
    """Anasayfa pozisyon kartları — seçili sanal defterin açık pozisyonları."""
    key, label, slot, _init = _home_display_ctx()
    state = load_state(key, slot)
    out: list[dict] = []
    for pos in state.get("open_positions") or []:
        spent = pos.get("pm_spent") or pos.get("amount")
        if not spent or not pos.get("symbol"):
            continue
        out.append({**pos, "_analiz": key, "_analiz_label": label})
    return out


def _display_pm_recent_trades(*, limit: int = 20) -> tuple[list[dict], list[dict]]:
    """(bekleyen açık, kapanmış) — anasayfa Son İşlemler paneli."""
    key, label, slot, _init = _home_display_ctx()
    state = load_state(key, slot)
    pending = []
    for p in state.get("open_positions") or []:
        if not (p.get("pm_spent") or p.get("amount")) or not p.get("symbol"):
            continue
        pending.append(_format_display_pm_open(p, label))
    recent: list[dict] = []
    for t in reversed(_home_display_hist(key, slot, state)):
        row = _format_display_pm_trade(t, label)
        if row:
            recent.append(row)
        if len(recent) >= limit:
            break
    return pending, recent


def _display_pm_balance() -> tuple[float, float]:
    """(nakit, portföy) — sanal defter bakiyesi + açık pozisyon riski."""
    key, _label, slot, init_bal = _home_display_ctx()
    state = load_state(key, slot)
    cash = float(state.get("balance") or init_bal)
    open_val = sum(
        float(p.get("pm_spent") or p.get("amount") or 0)
        for p in state.get("open_positions") or []
        if (p.get("pm_spent") or p.get("amount")) and p.get("symbol")
    )
    return round(cash, 2), round(cash + open_val, 2)


def _live_system_closed_stats(key: str, label: str) -> dict:
    """Tek gerçek PM trader — kapanmış işlem WR."""
    wins = losses = 0
    pnl = 0.0
    for t in _load_trader_history(key):
        row = _format_local_pm_trade(t, label)
        if not row:
            continue
        if row.get("win"):
            wins += 1
        else:
            losses += 1
        pnl += float(row.get("pnl") or 0)
    total = wins + losses
    return {
        "closed_trades": total,
        "wins": wins,
        "losses": losses,
        "wr": round(wins / total * 100, 1) if total else None,
        "pnl": round(pnl, 2),
    }


def _live_system_open_stats(key: str) -> tuple[int, int]:
    """(açık pozisyon, şu an kazanan yönde)."""
    open_n = winning = 0
    for pos in load_state(key).get("open_positions", []):
        if not _position_visible(key, pos):
            continue
        open_n += 1
        sym = pos.get("symbol")
        entry = float(pos.get("entry_price") or 0)
        pred = pos.get("predicted_dir") or pos.get("pm_token_dir") or ""
        if not sym or not entry or pred not in ("UP", "DOWN"):
            continue
        try:
            cur = get_price(sym)
            if cur is None:
                continue
            actual = "UP" if float(cur) >= entry else "DOWN"
            if actual == pred:
                winning += 1
        except Exception:
            pass
    return open_n, winning


def _real_pm_overview_stats() -> dict:
    """Overview üst kartlar — anasayfada seçili sanal defter gerçek PM gibi."""
    key, label, slot, init_bal = _home_display_ctx()
    state = load_state(key, slot)
    hist = _home_display_hist(key, slot, state)
    graded = [t for t in hist if t.get("win") is not None]
    wins = sum(1 for t in graded if t.get("win"))
    losses = len(graded) - wins
    total = len(graded)
    wr = round(wins / total * 100, 1) if total else 0.0
    pnl = round(sum(float(t.get("pnl") or 0) for t in graded), 2)
    cash, portfolio = _display_pm_balance()
    open_n = sum(
        1 for p in state.get("open_positions") or []
        if (p.get("pm_spent") or p.get("amount")) and p.get("symbol")
    )

    history: list[dict] = []
    for t in reversed(graded):
        row = _format_display_pm_trade(t, label)
        if row:
            history.append(row)
        if len(history) >= 15:
            break

    return {
        "total_pnl": pnl,
        "baseline": init_bal,
        "cash": cash,
        "portfolio": portfolio,
        "source": "display_book",
        "display_book": key,
        "display_label": label,
        "display_slot": slot,
        "closed_trades": total,
        "wins": wins,
        "losses": losses,
        "wr": wr,
        "open": open_n,
        "history": history,
    }


def get_pm_token_price(pm_slug: str, token_dir: str) -> float | None:
    """Polymarket'tan anlık token fiyatını çeker (0-1 arası)."""
    try:
        url = f"{_PM_GAMMA}/events?slug={pm_slug}"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            data = json.load(r)
        if not data:
            return None
        m = data[0].get("markets", [{}])[0]
        raw = m.get("outcomePrices")
        op  = json.loads(raw) if isinstance(raw, str) else (raw or [])
        if len(op) >= 2:
            return float(op[0]) if token_dir == "UP" else float(op[1])
    except Exception:
        pass
    return None


def get_pm_hourly_quotes(only_names: set[str] | None = None) -> list[dict]:
    """Aktif 1h PM marketleri — BTC/SOL UP/DOWN anlık fiyat (A1 Live ile aynı slug)."""
    from datetime import timedelta
    import time as _time

    if only_names is not None and not only_names:
        return []

    cache_key = tuple(sorted(only_names)) if only_names is not None else ("*",)
    now = _time.time()
    if (
        _PM_HOURLY_Q_CACHE.get("rows") is not None
        and _PM_HOURLY_Q_CACHE.get("key") == cache_key
        and now - float(_PM_HOURLY_Q_CACHE.get("ts") or 0) < _PM_QUOTE_CACHE_TTL
    ):
        return list(_PM_HOURLY_Q_CACHE["rows"])

    try:
        sys.path.insert(0, _DIR_POLY)
        from poly_trader_analiz5 import _pm_find_market
    except Exception:
        return []

    now_utc = datetime.now(timezone.utc)
    et_hour = (now_utc - timedelta(hours=4)).hour
    out: list[dict] = []

    for sym in ("BTCUSDT", "SOLUSDT"):
        name = sym.replace("USDT", "")
        if only_names is not None and name not in only_names:
            continue
        row: dict = {"symbol": sym, "name": name}
        try:
            row["binance"] = round(get_price(sym), 2 if name == "BTC" else 4)
        except Exception:
            row["binance"] = None

        try:
            pm = _pm_find_market(sym, et_hour, now_utc)
        except Exception:
            pm = None

        if not pm:
            row["error"] = "market yok"
            out.append(row)
            continue

        op = pm.get("outcome_prices") or []
        up_p = float(op[0]) if len(op) > 0 else None
        down_p = float(op[1]) if len(op) > 1 else None
        title = pm.get("title") or ""
        # "Bitcoin Up or Down - July 21, 10AM ET" → "10AM ET"
        hour_lbl = title.split(",")[-1].strip() if "," in title else title

        row.update({
            "title": title,
            "hour_et": hour_lbl,
            "slug": pm.get("slug", ""),
            "up": round(up_p, 3) if up_p is not None else None,
            "down": round(down_p, 3) if down_p is not None else None,
            "up_cents": round(up_p * 100, 1) if up_p is not None else None,
            "down_cents": round(down_p * 100, 1) if down_p is not None else None,
            "closed": bool(pm.get("closed")),
        })
        out.append(row)

    _PM_HOURLY_Q_CACHE["ts"] = now
    _PM_HOURLY_Q_CACHE["key"] = cache_key
    _PM_HOURLY_Q_CACHE["rows"] = out
    return list(out)


def get_pm_15m_quotes(only_names: set[str] | None = None) -> list[dict]:
    """Aktif 15m PM up/down — BTC/SOL (110/210 ile aynı slug)."""
    import time

    if only_names is not None and not only_names:
        return []

    cache_key = tuple(sorted(only_names)) if only_names is not None else ("*",)
    now_f = time.time()
    if (
        _PM_15M_Q_CACHE.get("rows") is not None
        and _PM_15M_Q_CACHE.get("key") == cache_key
        and now_f - float(_PM_15M_Q_CACHE.get("ts") or 0) < _PM_QUOTE_CACHE_TTL
    ):
        return list(_PM_15M_Q_CACHE["rows"])

    try:
        sys.path.insert(0, _DIR_POLY)
        from pm_trader_helpers import pm_15m_find_market
    except Exception:
        return []

    now = int(time.time())
    ts_period = now - (now % 900)
    period_tr = datetime.fromtimestamp(ts_period, _TZ_TR).strftime("%H:%M")
    out: list[dict] = []

    for sym in ("BTCUSDT", "SOLUSDT"):
        name = sym.replace("USDT", "")
        if only_names is not None and name not in only_names:
            continue
        row: dict = {"symbol": sym, "name": name}
        try:
            row["binance"] = round(get_price(sym), 2 if name == "BTC" else 4)
        except Exception:
            row["binance"] = None

        try:
            pm = pm_15m_find_market(ts_period, sym)
        except Exception:
            pm = None

        if not pm:
            row["error"] = "market yok"
            out.append(row)
            continue

        up_p = float(pm.get("up_price", 0))
        down_p = float(pm.get("down_price", 0))
        title = pm.get("title") or ""
        period_lbl = title.split(",")[-1].strip() if "," in title else f"{period_tr} İST"

        row.update({
            "title": title,
            "period_lbl": period_lbl,
            "period_tr": period_tr,
            "slug": pm.get("slug", ""),
            "up": round(up_p, 3),
            "down": round(down_p, 3),
            "up_cents": round(up_p * 100, 1),
            "down_cents": round(down_p * 100, 1),
            "closed": bool(pm.get("closed")),
        })
        out.append(row)

    _PM_15M_Q_CACHE["ts"] = now_f
    _PM_15M_Q_CACHE["key"] = cache_key
    _PM_15M_Q_CACHE["rows"] = out
    return list(out)

