@app.route("/poly/api/a2-trader-stats")
def api_a2_trader_stats():
    """A2#01–17 sanal trader WR listesi."""
    if _auth_required():
        return jsonify({"error": "unauthorized"}), 401
    rows = []
    for key in _A2_KEYS:
        hist = _load_trader_history(key)
        if not hist:
            continue
        total = len(hist)
        if total < 1:
            continue
        wins = sum(1 for t in hist if t.get("win"))
        wr = round(wins / total * 100, 1) if total else 0
        rows.append({
            "key": key,
            "label": _ANALYSIS_LABELS.get(key, key),
            "short": _OVERVIEW_SHORT_LABELS.get(key, key),
            "total": total,
            "wins": wins,
            "wr": wr,
            "pnl": round(sum(float(t.get("pnl") or 0) for t in hist), 2),
        })
    rows.sort(key=lambda r: (r["wr"], r["total"]), reverse=True)
    return jsonify({"algos": rows})


@app.route("/poly/api/symbol_stats")
def api_symbol_stats():
    if _auth_required(): return redirect("/poly/login")
    # Sabit panel yerine: 1s en başarılı analiz (WR) — refresh ile güncellenir
    forced = request.args.get("analiz")
    best = _best_hourly_analiz(min_trades=30)
    if forced and forced in _HEATMAP_ANALYSES:
        analiz_key = forced
    elif best:
        analiz_key = best["analiz"]
    else:
        analiz_key = _PANEL_STATS_ANALIZ
    hist = _load_heatmap_history(analiz_key)
    # Sembol kartları: her coin için en yüksek WR'li analiz (karışık olabilir)
    sym_wr = _best_analiz_by_symbol(min_trades=5)
    if not hist:
        label = _ANALYSIS_LABELS.get(analiz_key, analiz_key)
        top_slots, bottom_slots = _best_hour_slots_across_analyses(top_n=3, min_trades=3)
        if sym_wr:
            total = sum(r["t"] for r in sym_wr)
            total_wins = sum(r["w"] for r in sym_wr)
            total_wr = round(total_wins / total * 100, 1) if total else 0.0
            shorts = []
            for r in sym_wr:
                s = r.get("analiz_short") or r.get("analiz_label") or r.get("analiz")
                if s and s not in shorts:
                    shorts.append(s)
            mix_short = " · ".join(shorts) if shorts else "—"
            mix_label = "Coin başına en iyi: " + ", ".join(
                f"{r['sym']}→{r.get('analiz_short') or r.get('analiz')}" for r in sym_wr
            )
        else:
            total, total_wins, total_wr = 0, 0, 0.0
            mix_short = _OVERVIEW_SHORT_LABELS.get(analiz_key, label)
            mix_label = label
        return jsonify({"analiz": analiz_key, "analiz_label": mix_label,
                        "analiz_short": mix_short,
                        "total": total, "total_wins": total_wins, "total_wr": total_wr, "sym_wr": sym_wr,
                        "top_slots": top_slots, "bottom_slots": bottom_slots, "dynamic_best": True})

    # Mor kart başlığı — coin başına en iyi analizlerin birleşik WR
    if sym_wr:
        total = sum(r["t"] for r in sym_wr)
        total_wins = sum(r["w"] for r in sym_wr)
        total_wr = round(total_wins / total * 100, 1) if total else 0.0
        shorts = []
        for r in sym_wr:
            s = r.get("analiz_short") or r.get("analiz_label") or r.get("analiz")
            if s and s not in shorts:
                shorts.append(s)
        sym_mix_short = " · ".join(shorts) if shorts else "—"
        sym_mix_label = "Coin başına en iyi: " + ", ".join(
            f"{r['sym']}→{r.get('analiz_short') or r.get('analiz')}" for r in sym_wr
        )
    elif best and analiz_key == best["analiz"] and not forced:
        total = best["total"]
        total_wins = best["total_wins"]
        total_wr = best["total_wr"]
        sym_mix_short = best["analiz_short"]
        sym_mix_label = best["analiz_label"]
    else:
        total = len(hist)
        total_wins = sum(1 for t in hist if t.get("win"))
        total_wr = round(total_wins / total * 100, 1) if total else 0.0
        label_fb = _ANALYSIS_LABELS.get(analiz_key, analiz_key)
        sym_mix_short = _OVERVIEW_SHORT_LABELS.get(analiz_key, label_fb)
        sym_mix_label = label_fb

    # En etkili / zayıf saatler — TÜM 1s analizlerde tarama (saat başına en iyi/kötü analiz)
    top_slots, bottom_slots = _best_hour_slots_across_analyses(top_n=3, min_trades=3)
    label = _ANALYSIS_LABELS.get(analiz_key, analiz_key)
    return jsonify({
        "analiz": analiz_key,
        "analiz_label": sym_mix_label if sym_wr else label,
        "analiz_short": sym_mix_short if sym_wr else _OVERVIEW_SHORT_LABELS.get(analiz_key, label),
        "total": total,
        "total_wins": total_wins,
        "total_wr": total_wr,
        "sym_wr": sym_wr,
        "top_slots": top_slots,
        "bottom_slots": bottom_slots,
        "dynamic_best": True,
    })

def _fmt_tr_date_short(iso: str | None) -> str | None:
    """ISO zaman → dd.mm.yyyy."""
    if not iso or len(iso) < 10:
        return None
    try:
        y, m, d = iso[:10].split("-")
        return f"{d}.{m}.{y}"
    except Exception:
        return iso[:10]


def _poly_book_started_at(
    state: dict,
    hist_stats: list,
    hist_all: list,
    reset_at: str | None,
) -> tuple[str | None, str | None]:
    """(iso, dd.mm.yyyy) — reset sonrası dönem veya ilk işlem."""
    raw: str | None = None
    if reset_at:
        raw = reset_at
    else:
        pool = hist_stats or hist_all
        times = [t.get("entry_time_tr") for t in pool if t.get("entry_time_tr")]
        if times:
            raw = min(times)
        else:
            opens = state.get("open_positions") or []
            ot = [p.get("entry_time_tr") for p in opens if p.get("entry_time_tr")]
            if ot:
                raw = min(ot)
    if not raw:
        return None, None
    return raw, _fmt_tr_date_short(raw)


def _build_single_poly_book(key: str, *, include_history: bool = False,
                            slot: int | None = None) -> dict | None:
    """Tek Poly sanal defter — A6 veya A2#xx. slot=5/7 → t05/t07 kopya."""
    open_min = 2 if slot is None else int(slot)
    init_bal = float(_OVERVIEW_INIT_BAL.get(key, 300) or 300)
    label = _ANALYSIS_LABELS.get(key, key)
    short = _OVERVIEW_SHORT_LABELS.get(key, key)
    hpath = _trader_history_path(key, open_min)
    spath = _trader_state_path(key, open_min)
    has_files = os.path.exists(hpath) or os.path.exists(spath)
    if not has_files and key not in _ALGO_ISLEMLER_KEYS:
        return None
    try:
        hist = _load_trader_history(key, open_min) if os.path.exists(hpath) else []
        state = json.load(open(spath, encoding="utf-8")) if os.path.exists(spath) else {
            "balance": init_bal,
            "open_positions": [],
            "total_pnl": 0.0,
        }
    except Exception:
        return None
    try:
        if state.get("initial_balance") is not None:
            init_bal = float(state["initial_balance"])
    except (TypeError, ValueError):
        pass
    reset_at = state.get("balance_reset_at_tr")
    hist_stats = hist
    if reset_at:
        hist_stats = [
            t for t in hist
            if (t.get("exit_time_tr") or "") >= reset_at
        ]
    bal = round(float(state.get("balance") or init_bal), 2)
    total = len(hist_stats)
    wins = sum(1 for t in hist_stats if t.get("win"))
    wr = round(wins / total * 100, 1) if total else None
    realized = round(float(state.get("total_pnl") or 0), 2)
    open_spent = 0.0
    for _p in state.get("open_positions") or []:
        try:
            open_spent += float(_p.get("pm_spent") or _p.get("amount") or 0)
        except (TypeError, ValueError):
            pass
    # 2. Analiz gibi defterler bileti bakiyeden düşer; açık tutarı zarar yazma.
    if open_spent > 0 and (bal + open_spent) <= (init_bal + realized + 1.0):
        pnl = realized
    else:
        pnl = round(bal - init_bal, 2)
    allowed = set(_allowed_syms_for(key))
    from pm_trader_helpers import pm_payout_fields
    cards = []
    for idx, p in enumerate(state.get("open_positions") or []):
        sym_raw = (p.get("symbol") or "")
        sym = sym_raw.replace("USDT", "")
        if sym and allowed and sym not in allowed:
            continue
