def _jarvis2026_snapshot() -> dict:
    """JARVIS2026 evrim politikası + son notlar — detay kartı."""
    pol_path = os.path.join(_DIR_POLY, "jarvis2026_policy.json")
    feed_path = os.path.join(_DIR_POLY, "jarvis2026_feed.jsonl")
    try:
        pol = json.load(open(pol_path, encoding="utf-8"))
        if not isinstance(pol, dict):
            pol = {}
    except Exception:
        pol = {}
    feed: list[dict] = []
    try:
        with open(feed_path, encoding="utf-8") as f:
            lines = f.readlines()[-8:]
        for line in reversed(lines):
            try:
                rec = json.loads(line)
            except Exception:
                continue
            if isinstance(rec, dict):
                feed.append({
                    "ts": str(rec.get("ts") or "")[:16],
                    "title": rec.get("title") or "",
                    "body": rec.get("body") or "",
                })
    except Exception:
        pass
    try:
        sys.path.insert(0, _DIR_POLY)
        from jarvis2026_signal import book_label
    except Exception:
        def book_label(k):  # type: ignore
            return k or "—"
    sources = []
    src = pol.get("sources") or {}
    for coin, sym in (("BTC", "BTCUSDT"), ("ETH", "ETHUSDT"), ("SOL", "SOLUSDT")):
        row = src.get(sym) if isinstance(src, dict) else {}
        if not isinstance(row, dict):
            row = {}
        book = str(row.get("book") or "")
        sources.append({
            "coin": coin,
            "book": book,
            "label": book_label(book) if book else "—",
            "why": str(row.get("why") or "")[:160],
        })
    ideas = []
    for raw in pol.get("ideas") or []:
        if not isinstance(raw, dict):
            continue
        ideas.append({
            "id": raw.get("id") or "",
            "symbol": str(raw.get("symbol") or "").replace("USDT", ""),
            "mode": raw.get("dir_mode") or raw.get("mode") or "",
            "book": book_label(str(raw.get("book") or "")) if raw.get("book") else "—",
            "ask_max": raw.get("ask_max"),
            "why": str(raw.get("why") or "")[:140],
            "lesson": str(raw.get("lesson") or "")[:140],
        })
    return {
        "generation": int(pol.get("generation") or 0),
        "source": pol.get("source") or "",
        "note": pol.get("note") or "",
        "updated_at_tr": str(pol.get("updated_at_tr") or "")[:16],
        "scan_books": pol.get("scan_books"),
        "sources": sources,
        "ideas": ideas,
        "feed": feed[:6],
    }


def _chip_from_book_row(row: dict | None, slot: int) -> dict:
    if not row:
        return {
            "slot": slot, "wr": None, "history_n": 0, "wins": 0,
            "balance": 1000.0, "total_pnl": 0.0, "open_count": 0, "best": False,
        }
    return {
        "slot": slot,
        "wr": row.get("wr"),
        "history_n": row.get("history_n") or 0,
        "wins": row.get("wins") or 0,
        "balance": row.get("balance"),
        "total_pnl": row.get("total_pnl"),
        "open_count": row.get("open_count") or 0,
        "best": False,
    }


def _poly_book_slot_chip(key: str, slot: int) -> dict:
    """Liste çipi — WR / işlem / bakiye."""
    row = _build_single_poly_book(key, slot=slot)
    return _chip_from_book_row(row, slot)


def _pick_best_slot(chips: dict) -> int:
    """:02/:05/:07 içinde en çok kazandıran dilim — net P&L, sonra WR."""
    scored = []
    for s in _SLOT_MINUTES:
        c = chips.get(s) or chips.get(str(s)) or {}
        n = int(c.get("history_n") or 0)
        if n <= 0:
            continue
        wr = c.get("wr")
        wr_v = float(wr) if wr is not None else -1.0
        pnl = float(c.get("total_pnl") or 0)
        scored.append((pnl, wr_v, n, -abs(int(s) - 5), int(s)))
    if not scored:
        return 5
    scored.sort(reverse=True)
    return int(scored[0][-1])


def _remember_best_slots(by_key: dict) -> None:
    _BEST_SLOT_CACHE["ts"] = time.time()
    _BEST_SLOT_CACHE["by_key"] = {str(k): int(v) for k, v in (by_key or {}).items()
                                  if v in _SLOT_MINUTES}


def _best_slot_for_book(key: str) -> int:
    """Ayna / liste — bu defterin en iyi açılış dakikası."""
    if key in _STANDALONE_MINUTE_BOOKS:
        return 2
    now = time.time()
    cached = _BEST_SLOT_CACHE.get("by_key") or {}
    if now - float(_BEST_SLOT_CACHE.get("ts") or 0) < _BEST_SLOT_TTL:
        hit = cached.get(key)
        if hit in _SLOT_MINUTES:
            return int(hit)
    chips = {s: _poly_book_slot_chip(key, s) for s in _SLOT_MINUTES}
    best = _pick_best_slot(chips)
    cached = dict(cached)
    cached[key] = best
    if now - float(_BEST_SLOT_CACHE.get("ts") or 0) >= _BEST_SLOT_TTL:
        _BEST_SLOT_CACHE["ts"] = now
    _BEST_SLOT_CACHE["by_key"] = cached
    return best


def _attach_slot_chips(row: dict) -> dict:
    key = row.get("id") or row.get("key")
    chips = {s: _poly_book_slot_chip(key, s) for s in _SLOT_MINUTES}
    best = 2 if key in _STANDALONE_MINUTE_BOOKS else _pick_best_slot(chips)
    for s, c in chips.items():
        c["best"] = s == best
    row["slots"] = chips
    row["best_slot"] = best
    row["mirror_slot"] = best
    return row


def _vote_coins_from_books(books: list[dict]) -> list[dict]:
    """:05 açık yön — defter başına coin'de tek oy."""
    coins = ("BTC", "ETH", "SOL")
    tallies = {c: {"up": 0, "down": 0} for c in coins}
    for b in books or []:
        seen: set[str] = set()
        for card in b.get("cards") or []:
            name = str(card.get("name") or card.get("symbol") or "").replace("USDT", "").upper()
            if name not in tallies or name in seen:
                continue
            seen.add(name)
            side = str(card.get("side") or "").upper()
            dir_tr = str(card.get("dir_tr") or "").upper()
            up = side in ("LONG", "UP") or dir_tr in ("YÜKSELİR", "YUKSELIR")
            if up:
                tallies[name]["up"] += 1
            else:
                tallies[name]["down"] += 1
    out = []
    for sym in coins:
        up = int(tallies[sym]["up"])
        down = int(tallies[sym]["down"])
        n = up + down
        if n == 0:
            winner, label, votes = None, "oy yok", 0
        elif up > down:
            winner, label, votes = "UP", "yükselir", up
        elif down > up:
            winner, label, votes = "DOWN", "düşer", down
        else:
            winner, label, votes = "TIE", "berabere", up
        if n == 0:
            text = f"{sym} · oy yok"
        elif winner == "TIE":
            text = f"{sym} berabere · {up}–{down}"
        else:
            text = f"{sym} {label} · {votes} oy"
        out.append({
            "symbol": sym,
            "up": up,
            "down": down,
            "n": n,
            "winner": winner,
            "label": label,
            "votes": votes,
            "text": text,
        })
    return out


def _regime_book_stats(books: list[dict]) -> dict:
    """Grup başarısı — seçili dilimdeki defter WR'si (wins / işlem)."""
    wins = sum(int(b.get("wins") or 0) for b in books or [])
    n = sum(int(b.get("history_n") or 0) for b in books or [])
    wr = round(100.0 * wins / n, 1) if n else None
    pnl = round(sum(float(b.get("total_pnl") or 0) for b in books or []), 2)
    return {
        "ok": True,
        "scored": n,
        "wins": wins,
        "wr": wr,
        "pnl": pnl,
        "label": (f"%{wr:g} başarılı".replace(".", ",") if wr is not None else "henüz sonuç yok"),
        "detail": f"{wins}/{n} işlem" if n else "işlem yok",
        "coins": {},
    }


def _card_dir(card: dict) -> str | None:
    side = str(card.get("side") or "").upper()
    dir_tr = str(card.get("dir_tr") or "").upper()
    if side in ("LONG", "UP") or dir_tr in ("YÜKSELİR", "YUKSELIR"):
        return "UP"
    if side in ("SHORT", "DOWN") or dir_tr in ("DÜŞER", "DUSER"):
        return "DOWN"
    return None


def _symbest_vote_group(slot_books: list[dict] | None) -> dict:
    """Her coinde en yüksek WR algoritmanın :05 yönü — TOP4 kaynağı."""
    by_id = {str(b.get("id") or ""): b for b in (slot_books or [])}
    items = _best_analiz_by_symbol(min_trades=5)
    coins = []
    used = []
    for r in items:
        key = str(r.get("analiz") or "")
        book = by_id.get(key)
        if book:
            used.append(book)
        winner = None
        for card in (book or {}).get("cards") or []:
            name = str(card.get("name") or card.get("symbol") or "").replace("USDT", "").upper()
            name = name.split("·")[0].strip()
            if name != str(r.get("sym") or "").upper():
                continue
            winner = _card_dir(card)
            break
        short = r.get("analiz_short") or key or "—"
        if winner == "UP":
            label, votes, up, down, n = f"yükselir · {short}", 1, 1, 0, 1
        elif winner == "DOWN":
            label, votes, up, down, n = f"düşer · {short}", 1, 0, 1, 1
        else:
            label, votes, up, down, n = f"açık yok · {short}", 0, 0, 0, 0
        coins.append({
            "symbol": r.get("sym"),
            "up": up,
            "down": down,
            "n": n,
            "winner": winner,
            "label": label,
            "votes": votes,
            "analiz": key,
            "analiz_short": short,
            "text": f"{r.get('sym')} → {short} {winner or 'bekliyor'}",
        })
    return {
        "regime": "symbest",
        "label": "Sembol",
        "books": len(items),
        "coins": coins,
        "stats": _regime_book_stats(used),
    }


def _algo_consensus_votes(books: list[dict], list_books: list[dict] | None = None,
                          slot_books: list[dict] | None = None) -> dict:
    """:05 açık yön — yalnız listedeki en iyi N defter (net P&L)."""
    now = datetime.now(_TZ_TR)
    slot_h = now.hour if now.minute >= 5 else (now.hour - 1) % 24
    out = _vote_coins_from_books(books)
    votes = {
        "ok": True,
        "slot": 5,
        "slot_open_tr": f"{slot_h:02d}:05",
        "books": len(books or []),
        "source": "top_pnl",
        "source_n": _VOTE_TOP_N,
        "coins": out,
    }
    try:
        sys.path.insert(0, _DIR_POLY)
        from algo_consensus_log import attach_to_votes
        votes = attach_to_votes(votes)
    except Exception:
        votes["stats"] = {"ok": False, "scored": 0, "wr": None, "label": "kayıt yok", "detail": ""}
    src = list_books if list_books is not None else books
    groups = []
    for rg in _REGIME_ORDER:
        vb = [b for b in (books or []) if (b.get("regime") or "live") == rg]
        lb = [b for b in (src or []) if (b.get("regime") or "live") == rg]
        if not lb and not vb:
            continue
        groups.append({
            "regime": rg,
            "label": _REGIME_LABEL.get(rg, rg),
            "books": len(lb),
            "coins": _vote_coins_from_books(vb),
            "stats": _regime_book_stats(lb),
        })
    groups.append(_symbest_vote_group(slot_books if slot_books is not None else books))
    votes["groups"] = groups
    votes["source_ids"] = [b.get("id") for b in (src or [])]
    try:
        from vote_paper import attach_paper
        votes = attach_paper(votes, persist=True)
    except Exception:
        pass
    return votes


def _ym_tr_label(ym: str) -> str:
    try:
        y, m = ym.split("-")
        return f"{_TR_MONTH_SHORT[int(m) - 1]} {y[2:]}"
    except Exception:
        return ym


def _bt_ranked_monthly(path: str, book_id: str) -> tuple[dict[str, float], float, str]:
    """(monthly_pnl, year_pnl, period) from a 1Y JSON."""
    try:
        data = json.loads(open(path, encoding="utf-8").read())
    except Exception:
        return {}, 0.0, ""
    rows = data.get("ranked") or data.get("algos") or data.get("results") or []
    hit = next((r for r in rows if str(r.get("id") or "") == book_id), None)
    if not hit:
        return {}, 0.0, str(data.get("period") or "")
    monthly = {str(k): float(v) for k, v in (hit.get("monthly_pnl") or {}).items()}
    return monthly, float(hit.get("total_pnl") or 0), str(hit.get("period") or data.get("period") or "")


_WATCH_BT_CACHE: dict = {"sig": "", "data": None}


def _watch_last_year_ym(now: datetime | None = None) -> str:
    t = now or datetime.now(_TZ_TR)
    return f"{t.year - 1:04d}-{t.month:02d}"


def _watch_month_backtest(books: list | None = None) -> dict:
    """İzleme 1Y — geçen yılın aynı ayı vs bu ay canlı settle."""
    now = datetime.now(_TZ_TR)
    ym = _watch_last_year_ym(now)
    p_watch = os.path.join(_DIR_POLY, "backtest_watch_1y.json")
    p_all = os.path.join(_DIR_POLY, "backtest_algo_islemler_1y.json")
    p_sel = os.path.join(_DIR_POLY, "backtest_selected_algos_1y.json")
    try:
        sig = (
            f"{ym}:{os.path.getmtime(p_watch) if os.path.isfile(p_watch) else 0:.0f}"
            f":{os.path.getmtime(p_all) if os.path.isfile(p_all) else 0:.0f}"
            f":{os.path.getmtime(p_sel) if os.path.isfile(p_sel) else 0:.0f}"
        )
    except OSError:
        sig = ym
    cached = _WATCH_BT_CACHE.get("data")
    if cached and _WATCH_BT_CACHE.get("sig") == sig:
        live_map = {str(b.get("id")): b for b in (books or [])}
        rows = []
        for row in cached.get("rows") or []:
            live = live_map.get(row["id"]) or {}
            rows.append({
                **row,
                "live_pnl": float(live.get("month_pnl") or 0),
                "live_n": int(live.get("month_n") or 0),
            })
        return {**cached, "rows": rows}

    fallback = {
        "analiz1": (p_sel, "analiz1"),
        "a2_03": (p_all, "a2_03"),
        "a2_05": (p_all, "a2_05"),
        "refsa": (p_watch, "refsa"),
        "ref04": (p_watch, "ref04"),
        "ref05": (p_watch, "ref05"),
        "ref06": (p_watch, "ref06"),
        "ref07": (p_watch, "ref07"),
        "jarvis2026": (p_watch, "jarvis2026"),
    }
    live_map = {str(b.get("id")): b for b in (books or [])}
    rows = []
    for key in _WATCH_PIN_KEYS:
        monthly, year_pnl, period = {}, 0.0, ""
        if os.path.isfile(p_watch):
            monthly, year_pnl, period = _bt_ranked_monthly(p_watch, key)
        if not monthly:
            src = fallback.get(key)
            if src:
                monthly, year_pnl, period = _bt_ranked_monthly(src[0], src[1])
        rows.append({
            "id": key,
            "label": _WATCH_PIN_LABEL.get(key, key),
            "month": ym,
            "month_label": _ym_tr_label(ym),
            "pnl": round(float(monthly.get(ym) or 0), 2),
            "year_pnl": round(year_pnl, 2),
            "period": period,
            "note": "geçen yıl aynı ay · 1Y walk-forward",
            "live_pnl": float((live_map.get(key) or {}).get("month_pnl") or 0),
            "live_n": int((live_map.get(key) or {}).get("month_n") or 0),
        })
    out = {
        "month": ym,
        "month_label": _ym_tr_label(ym),
        "rows": rows,
    }
    _WATCH_BT_CACHE["sig"] = sig
    _WATCH_BT_CACHE["data"] = {
        "month": out["month"],
        "month_label": out["month_label"],
        "rows": [{k: v for k, v in r.items() if k not in ("live_pnl", "live_n")} for r in rows],
    }
    return out


_A2_BOOKS_CACHE: dict = {"ts": 0.0, "data": None}
_A2_BOOKS_CACHE_TTL = 4.0


def _build_a2_poly_books() -> dict:
    """Poly sanal defterler — featured sarı kartlar + kalanlar (net P&L)."""
    now = time.time()
    hit = _A2_BOOKS_CACHE.get("data")
    if hit and now - float(_A2_BOOKS_CACHE.get("ts") or 0) < _A2_BOOKS_CACHE_TTL:
        return hit
    books = []
    vote_books = []
    best_map: dict[str, int] = {}
    for key in _ALGO_ISLEMLER_KEYS:
        built = {}
        for s in _SLOT_MINUTES:
            one = _build_single_poly_book(key, slot=s)
            if one:
                built[s] = one
        if not built:
            continue
        chips = {s: _chip_from_book_row(built.get(s), s) for s in _SLOT_MINUTES}
        best = 2 if key in _STANDALONE_MINUTE_BOOKS else _pick_best_slot(chips)
        for s, c in chips.items():
            c["best"] = s == best
        row = dict(built.get(best) or next(iter(built.values())))
        if not _algo_book_visible(row):
            continue
        row["slots"] = chips
        row["best_slot"] = best
        row["mirror_slot"] = best
        row["open_minute"] = best
        books.append(row)
        best_map[key] = best
        if 5 in built:
            vote_books.append(built[5])
    _remember_best_slots(best_map)
    _sort_algo_islemler_books(books, "id")
    _TOP_SKIP = ("top1", "top2", "top3", "top4")
    top_n = [b for b in books if not b.get("vote_paper") and str(b.get("id") or "") not in _TOP_SKIP][:_VOTE_TOP_N]
    top_ids = {b.get("id") for b in top_n}
    vote_top = [b for b in vote_books if b.get("id") in top_ids]
    home_key = get_pm_home_display_key()
    for b in books:
        b["is_home_display"] = b.get("id") == home_key
    votes = _algo_consensus_votes(vote_top, list_books=top_n, slot_books=vote_books)
    try:
        from vote_paper import list_top_books
        vote_rows = [
            b for b in (list_top_books() or [])
            if _algo_book_visible(b)
        ]
    except Exception:
        vote_rows = []
    all_books = vote_rows + books
    _sort_algo_islemler_books(all_books, "id")
    visible_ids = {str(b.get("id") or "") for b in all_books}
    book_bal = {str(b.get("id") or ""): float(b.get("balance") or 0) for b in all_books}
    watch_pin = [k for k in _WATCH_PIN_KEYS if k in visible_ids]
    watch_pin.sort(key=lambda k: book_bal.get(k, 0), reverse=True)
    watch_bt = _watch_month_backtest(books)
    bt_by_id = {r["id"]: r for r in (watch_bt.get("rows") or [])}
    for b in all_books:
        info = bt_by_id.get(str(b.get("id") or ""))
        if not info:
            continue
        b["bt_month"] = info.get("month")
        b["bt_month_label"] = info.get("month_label")
        b["bt_month_pnl"] = info.get("pnl")
        b["bt_year_pnl"] = info.get("year_pnl")
    out = {
        "ok": True,
        "panel_filter": "poly_algo",
        "books": all_books,
        "votes": votes,
        "home_display_book": home_key,
        "home_display_label": get_pm_home_display_label(home_key),
        "count": len(all_books),
        "sort": _ALGO_FEATURED_SORT,
        "featured": list(_ALGO_FEATURED_KEYS),
        "watch_pin": watch_pin,
        "watch_backtest": watch_bt,
        "total_balance": round(sum(float(b.get("balance") or 0) for b in books), 2),
        "total_pnl": round(sum(float(b.get("total_pnl") or 0) for b in books), 2),
        "total_open": sum(int(b.get("open_count") or 0) for b in books),
        "total_trades": sum(int(b.get("history_n") or 0) for b in books),
        "sym_best": _sym_best_card(min_trades=5),
    }
    _A2_BOOKS_CACHE["ts"] = now
    _A2_BOOKS_CACHE["data"] = out
    return out


def _patch_sanal_wr_amounts(key: str, body: dict) -> dict:
    """Poly sanal defter — sembol WR giriş kademelerini kaydet."""
    if key not in _ALGO_ISLEMLER_KEYS:
        raise ValueError("not found")
    try:
        low = float(body.get("amount_low", body.get("low")))
        mid = float(body.get("amount_mid", body.get("mid")))
        high = float(body.get("amount_high", body.get("high")))
    except (TypeError, ValueError):
        raise ValueError("geçersiz tutar") from None
    if low <= 0 or mid <= 0 or high <= 0:
        raise ValueError("tutarlar pozitif olmalı")
    sys.path.insert(0, _DIR_POLY)
    from pm_trader_helpers import save_sanal_wr_amounts
    save_sanal_wr_amounts(key, low, mid, high)
    book = _build_single_poly_book(key, include_history=True)
    if not book:
        raise ValueError("defter okunamadı")
    return book


@app.route("/poly/api/a2-algoritmalar/<book_id>/amounts", methods=["POST"])
def api_a2_algoritma_patch_amounts(book_id: str):
    """Poly sanal — sembol WR giriş tutarları ($ düşük/orta/yüksek)."""
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    key = _normalize_algo_book_id(book_id)
    if key not in _ALGO_ISLEMLER_KEYS:
        return jsonify({"ok": False, "error": "not found"}), 404
    try:
        body = request.get_json(silent=True) or {}
        book = _patch_sanal_wr_amounts(key, body)
        return jsonify({"ok": True, "book": book})
    except ValueError as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


