# ── Dış sunucu aynası ────────────────────────────────────────────
# Başka bir sunucu ":06'da A6V3 ne açtı?" diye sorup aynı işlemi kendi
# tarafında açabilsin diye makine okunur uç. Yalnızca OKUR: emir tetiklemez,
# hiçbir state dosyasına yazmaz. Oturum yerine sabit token ile korunur.
_MIRROR_MARKET_CACHE: dict[str, tuple[float, dict]] = {}
_MIRROR_MARKET_TTL = 8.0


def _mirror_token_ok() -> bool:
    expected = (os.environ.get("MIRROR_API_TOKEN") or "").strip()
    if not expected:
        return False   # token tanımlı değilse uç tamamen kapalı
    got = (request.headers.get("X-Mirror-Token") or request.args.get("token") or "").strip()
    return bool(got) and secrets.compare_digest(got, expected)


def _mirror_ask(token_id: str | None) -> float | None:
    """CLOB best_ask — okunamazsa None döner, çağıran mid'e düşer."""
    if not token_id:
        return None
    try:
        sys.path.insert(0, _DIR_POLY)
        from pm_trader_helpers import pm_best_ask
        px = pm_best_ask(token_id)
        return float(px) if px else None
    except Exception:
        return None


def _mirror_market(slug: str) -> dict:
    """slug → CLOB token id'leri + alınabilir fiyat. Aynı slot'ta çok çağrılırsa Gamma'yı yormasın.

    Fiyat, emir defterinin gerçek best_ask'idir. Gamma'nın outcomePrices alanı
    son işlem fiyatı; saat başında 10+ puan bayat kalabiliyor ve o fiyattan alım
    yapılamıyor — aynanın tavan/taban kontrolleri bu yüzden yanlış sayıya
    bakıyordu. Mid bilgisi kaybolmasın diye ayrıca döndürülür.
    """
    now = time.time()
    hit = _MIRROR_MARKET_CACHE.get(slug)
    if hit and now - hit[0] < _MIRROR_MARKET_TTL:
        return hit[1]
    try:
        req = urllib.request.Request(f"{_PM_GAMMA}/events?slug={slug}",
                                     headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            data = json.load(r)
        m = (data[0].get("markets") or [{}])[0] if data else {}
        raw_tk = m.get("clobTokenIds")
        tokens = json.loads(raw_tk) if isinstance(raw_tk, str) else (raw_tk or [])
        raw_op = m.get("outcomePrices")
        prices = json.loads(raw_op) if isinstance(raw_op, str) else (raw_op or [])
        up_token   = tokens[0] if len(tokens) > 1 else None
        down_token = tokens[1] if len(tokens) > 1 else None
        up_mid     = float(prices[0]) if len(prices) > 1 else None
        down_mid   = float(prices[1]) if len(prices) > 1 else None
        up_ask, down_ask = _mirror_ask(up_token), _mirror_ask(down_token)
        out = {
            "up_token":   up_token,
            "down_token": down_token,
            "up_price":   up_ask if up_ask else up_mid,
            "down_price": down_ask if down_ask else down_mid,
            "up_mid":     up_mid,
            "down_mid":   down_mid,
            "up_src":     "ask" if up_ask else "mid",
            "down_src":   "ask" if down_ask else "mid",
            "tick_size":  str(m.get("orderPriceMinTickSize", "0.01")),
            "neg_risk":   bool(m.get("negRisk", False)),
            "closed":     bool(m.get("closed", False)),
        }
    except Exception as e:
        out = {"error": str(e)[:80]}
    _MIRROR_MARKET_CACHE[slug] = (now, out)
    return out


_MIRROR_MIN_SHARES = 5.0  # Polymarket alım minimumu — küçük bahisleri yukarı zorlar


def _mirror_policy() -> dict:
    """Kopyalama eşikleri tek yerde. Aynalar bu değerleri sorgulamaz, uygular.

    Fiyat eşiklerinin iki adı var: burada `MIRROR_ENTRY_PRICE_MIN/MAX`, ayna
    sunucusunun kendi kodunda `MIRROR_MIN/MAX_ENTRY_PRICE`. İkisi de okunur ve
    hangisinin geçerli olduğu `sources` altında bildirilir — yanlış anahtarı
    düzenleyip "neden değişmedi" diye aramamak için.
    """
    sources: dict[str, str] = {}

    def _f(key: str, default: float, *names: str) -> float:
        for env_name in names:
            raw = os.environ.get(env_name)
            if raw is None or str(raw).strip() == "":
                continue
            try:
                val = float(raw)
            except (TypeError, ValueError):
                continue
            sources[key] = env_name
            return val
        sources[key] = "default"
        return default

    return {
        "entry_price_min": _f("entry_price_min", 0.40,
                              "MIRROR_ENTRY_PRICE_MIN", "MIRROR_MIN_ENTRY_PRICE"),
        "entry_price_max": _f("entry_price_max", 0.75,
                              "MIRROR_ENTRY_PRICE_MAX", "MIRROR_MAX_ENTRY_PRICE"),
        "max_age_sec": _f("max_age_sec", 1200, "MIRROR_MAX_AGE_SEC"),
        "max_adverse_drift_pct": _f("max_adverse_drift_pct", 40.0, "MIRROR_MAX_ADVERSE_DRIFT_PCT"),
        "max_spend_ratio": _f("max_spend_ratio", 1.15, "MIRROR_MAX_SPEND_RATIO"),
        "min_shares": _MIRROR_MIN_SHARES,
        "sources": sources,
    }


def _mirror_block(code: str, detail: str) -> dict:
    return {"copyable": False, "block_reason": code, "block_detail": detail}


def _mirror_copy_decision(row: dict, pol: dict) -> dict:
    """Bu pozisyon şu an kopyalanmalı mı — karar burada verilir.

    Ayna tarafında tekrar akıl yürütülmesin diye engelin kodu ve okunabilir
    açıklaması birlikte döner. İlk engelde durur; sıralama en ucuzdan en
    pahalı kontrole doğrudur (fiyat kontrolü Gamma verisi gerektirir).
    """
    if not row.get("is_current_slot"):
        return _mirror_block("stale_slot", "pozisyon aktif slota ait değil")
    if row.get("stale"):
        return _mirror_block("stale", "kaynak pozisyonu bayat işaretledi")
    if row.get("dir") not in ("UP", "DOWN"):
        return _mirror_block("missing_dir", "yön belirsiz")
    age = row.get("age_sec")
    if age is not None and age > pol["max_age_sec"]:
        return _mirror_block(
            "too_old",
            f"sinyal {int(age)} sn eski (limit {int(pol['max_age_sec'])} sn)",
        )
    if row.get("pm_closed"):
        return _mirror_block("market_closed", "Polymarket marketi kapalı")
    if not row.get("pm_token_id"):
        return _mirror_block("missing_token", "CLOB token id okunamadı")
    px = row.get("pm_price_now")
    if px is None:
        return _mirror_block("no_price", "anlık PM fiyatı okunamadı")
    px = float(px)
    if px > pol["entry_price_max"]:
        return _mirror_block(
            "price_above_cap",
            f"fiyat {px:.2f} > tavan {pol['entry_price_max']:.2f}",
        )
    if pol["entry_price_min"] > 0 and px < pol["entry_price_min"]:
        return _mirror_block(
            "price_below_floor",
            f"fiyat {px:.2f} < taban {pol['entry_price_min']:.2f} — "
            "piyasa kaynağın tahminini yanlışlamış",
        )
    drift = row.get("pm_price_drift_pct")
    cap = pol["max_adverse_drift_pct"]
    if cap > 0 and drift is not None and float(drift) < -cap:
        return _mirror_block(
            "adverse_drift",
            f"fiyat kaynağın girişine göre %{float(drift):.0f} sapmış (limit -%{cap:.0f})",
        )
    return {"copyable": True, "block_reason": None, "block_detail": None}


def _mirror_min_stake(px: float | None, pol: dict) -> float | None:
    """Borsa minimumu bahsi şişirmeden bu pozisyona girilebilecek en küçük tutar.

    5 share zorunlu olduğu için maliyet her zaman 5*fiyat; bunun altındaki bir
    bahis niyetini aşar. Aynanın kendi kesesine göre karar verebilmesi için
    tutar değil, tutarın alt sınırı bildirilir.
    """
    if not px:
        return None
    ratio = pol["max_spend_ratio"] or 1.0
    return round(pol["min_shares"] * float(px) / ratio, 2)


def _mirror_query_slot() -> int | None:
    """`?slot=02` yalnız teşhis; yoksa None → dosyadaki seçim."""
    try:
        raw = request.args.get("slot")
    except Exception:
        return None
    if not raw:
        return None
    return _parse_open_slot(raw)


def _mirror_open_minute(book: str | None = None) -> int:
    try:
        ov = _mirror_query_slot()
    except ValueError:
        ov = None
    if ov is not None:
        return ov
    if book:
        return _best_slot_for_book(book)
    return 5


def _mirror_slot_minutes(book: str | None = None) -> tuple[int, int]:
    """Seçili dilimin open dakikası / sonraki saat :01 close.

    Yayın: defterin :02/:05/:07 içinde en yüksek WR'li dilimi.
    :01 yeni open yok (önceki slot settle ile çakışır).
    """
    return _mirror_open_minute(book), 1


def _mirror_slot_fields(entry_hour: int, book: str | None = None) -> dict:
    """İST saatlik slot — :02 open → sonraki saat :01 close."""
    nh = (entry_hour + 1) % 24
    open_m, close_m = _mirror_slot_minutes(book)
    return {
        "entry_hour_tr": entry_hour,
        "slot_tr": f"{entry_hour:02d}:{open_m:02d}-{nh:02d}:{close_m:02d}",
        "slot_open_tr": f"{entry_hour:02d}:{open_m:02d}",
        "slot_close_tr": f"{nh:02d}:{close_m:02d}",
        "prediction_tr": f"{entry_hour:02d}:00-{nh:02d}:00",
    }


def _mirror_active_slot(now_tr: datetime | None = None, book: str | None = None) -> dict:
    """Şu an mirror'lanabilir slot.

    :02+ open · :01 pre_open (settle bitene kadar yeni slot yok) · :00 closing.
    Tahmin saati HH:00–HH+1:00 → pencere HH:02–HH+1:01.
    """
    now_tr = now_tr or datetime.now(_TZ_TR)
    h, m = now_tr.hour, now_tr.minute
    open_m, close_m = _mirror_slot_minutes(book)
    if m >= open_m:
        slot_h, slot_date = h, now_tr.date()
        phase = "open"
    elif m < close_m:
        if h == 0:
            slot_h = 23
            slot_date = (now_tr - timedelta(days=1)).date()
        else:
            slot_h, slot_date = h - 1, now_tr.date()
        phase = "closing"
    else:
        slot_h, slot_date = h, now_tr.date()
        phase = "pre_open"
    out = {
        "status": "active",
        "slot_phase": phase,
        "slot_date_tr": slot_date.isoformat(),
        **_mirror_slot_fields(slot_h, book),
    }
    if phase == "pre_open":
        out["message"] = (
            f"{slot_h:02d}:{close_m:02d} close sonrası, {slot_h:02d}:{open_m:02d} open öncesi — "
            f"pozisyonlar :{open_m:02d} cron sonrası gelir"
        )
    elif phase == "closing":
        out["message"] = (
            f"{slot_h:02d}:{open_m:02d} slotu kapanıyor ({(slot_h + 1) % 24:02d}:{close_m:02d} settle) — "
            f"yeni açılış :{open_m:02d}"
        )
    return out


def _mirror_pos_entry_hour(p: dict) -> tuple[int | None, date | None]:
    eh = p.get("entry_hour_tr")
    try:
        et = datetime.fromisoformat(str(p.get("entry_time_tr")).replace("Z", "+00:00"))
        et_tr = et.astimezone(_TZ_TR)
    except Exception:
        return (int(eh) if eh is not None else None), None
    if eh is None:
        eh = et_tr.hour
    return int(eh), et_tr.date()


def _mirror_pos_slot_date(p: dict, eh: int | None) -> date | None:
    """Pozisyonun ait olduğu slot takvim günü (23:05 slotu gece yarısını geçer)."""
    try:
        et = datetime.fromisoformat(str(p.get("entry_time_tr")).replace("Z", "+00:00"))
        if et.tzinfo is None:
            et = et.replace(tzinfo=_TZ_TR)
        et_tr = et.astimezone(_TZ_TR)
    except Exception:
        return None
    if eh is None:
        eh = et_tr.hour
    slot_day = et_tr.date()
    # Nadiren entry_hour_tr=23 iken damga 00:0x'e kayarsa önceki güne bağla
    open_m = _mirror_open_minute(None)
    if int(eh) == 23 and et_tr.hour == 0 and et_tr.minute < max(5, open_m):
        slot_day = slot_day - timedelta(days=1)
    return slot_day


def _mirror_pos_matches_slot(p: dict, slot: dict) -> bool:
    if slot.get("status") != "active":
        return False
    eh, _ed = _mirror_pos_entry_hour(p)
    if eh is None:
        return False
    slot_day = _mirror_pos_slot_date(p, eh)
    if slot_day is None:
        return False
    return eh == slot["entry_hour_tr"] and slot_day.isoformat() == slot["slot_date_tr"]


def _mirror_rows(key: str, *, with_market: bool, current_only: bool = True) -> list[dict]:
    spath = _trader_state_path(key, _mirror_open_minute(key))
    if not os.path.exists(spath):
        return []
    try:
        with open(spath, encoding="utf-8") as f:
            state = json.load(f)
    except Exception:
        return []
    allowed = set(_allowed_syms_for(key))
    now = datetime.now(_TZ_TR)
    active_slot = _mirror_active_slot(now, key)
    pol = _mirror_policy()
    rows: list[dict] = []
    for p in state.get("open_positions") or []:
        sym_raw = p.get("symbol") or ""
        sym = sym_raw.replace("USDT", "")
        if sym and allowed and sym not in allowed:
            continue
        eh, _ed = _mirror_pos_entry_hour(p)
        in_active = _mirror_pos_matches_slot(p, active_slot)
        if current_only and not in_active:
            continue
        direction = str(p.get("pm_token_dir") or p.get("predicted_dir") or "").upper()
        up = direction in ("UP", "LONG")
        row = {
            "symbol": sym or sym_raw,
            "symbol_raw": sym_raw,
            "dir": "UP" if up else "DOWN",
            "side": "LONG" if up else "SHORT",
            "amount_usd": p.get("amount"),
            "spot_entry": p.get("entry_price"),
            "algo_name": p.get("algo_name"),
            "pm_slug": p.get("pm_slug"),
            "pm_title": p.get("pm_title"),
            "pm_entry_price": p.get("pm_entry_price"),
            "pm_size": p.get("pm_size"),
            "entry_time_tr": p.get("entry_time_tr"),
            "is_current_slot": in_active,
            "stale": not in_active,
        }
        if eh is not None:
            row.update(_mirror_slot_fields(eh, key))
        # Defter dosyası bozulsa bile sabit kalan kimlik — ayna mükerrer
        # kontrolünü buna göre yapar, kendi anahtarını üretmez.
        if eh is not None and _ed is not None:
            row["position_id"] = f"{key}:{_ed.isoformat()}:{eh:02d}:{sym_raw}"
        # sinyalin yaşı: bu projede ölçülen en pahalı kalem gecikme kaynaklı kayma
        try:
            t0 = datetime.fromisoformat(str(p.get("entry_time_tr")).replace("Z", "+00:00"))
            if t0.tzinfo is None:
                t0 = t0.replace(tzinfo=_TZ_TR)
            row["age_sec"] = int((now - t0.astimezone(_TZ_TR)).total_seconds())
        except Exception:
            row["age_sec"] = None
        if with_market and row["pm_slug"]:
            mk = _mirror_market(row["pm_slug"])
            row["pm_token_id"]  = mk.get("up_token") if up else mk.get("down_token")
            row["pm_price_now"] = mk.get("up_price") if up else mk.get("down_price")
            # pm_price_now artık gerçek ask; mid'i de veriyoruz ki aynanın
            # kendi ölçümleri ve geçmiş karşılaştırmaları kopmasın.
            row["pm_mid_price"] = mk.get("up_mid") if up else mk.get("down_mid")
            row["pm_quote_src"] = mk.get("up_src") if up else mk.get("down_src")
            row["pm_tick_size"] = mk.get("tick_size")
            row["pm_neg_risk"]  = mk.get("neg_risk")
            row["pm_closed"]    = mk.get("closed")
            if mk.get("error"):
                row["pm_market_error"] = mk["error"]
            ref, cur = row.get("pm_entry_price"), row.get("pm_price_now")
            if ref and cur:
                # sanal defterin gördüğü fiyata göre şu an ne kadar pahalı
                row["pm_price_drift_pct"] = round((cur - ref) / ref * 100, 1)
            # Kopyalama kararı kaynakta verilir; ayna yalnızca uygular.
            row.update(_mirror_copy_decision(row, pol))
            row["entry_price_min"] = pol["entry_price_min"]
            row["entry_price_max"] = pol["entry_price_max"]
            row["min_stake_usd"] = _mirror_min_stake(row.get("pm_price_now"), pol)
        else:
            # Fiyat okunmadan kopyalanabilirliğe karar verilemez. Alanı hiç
            # yazmamak, aynada "engel yok" diye okunabiliyordu — kapalı başlat.
            row.update(_mirror_block("no_market_data", "fiyat verisi istenmedi (market=0)"))
        rows.append(row)
    return rows


