@app.route("/poly/api/mirror")
def api_mirror_index():
    """Defter listesi — /algoritma-islemler ile aynı sıra: seçili dilim P&L."""
    if not _mirror_token_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    now = datetime.now(_TZ_TR)
    try:
        _mirror_query_slot()
    except ValueError:
        return jsonify({"ok": False, "error": "slot 02/05/07"}), 400
    slot = _mirror_active_slot(now)
    include_all = (request.args.get("all") or "").lower() in ("1", "true", "yes")
    books = []
    for k in _ALGO_ISLEMLER_KEYS:
        n_slot = len(_mirror_rows(k, with_market=False, current_only=not include_all))
        row = _mirror_book_row(k, open_count=n_slot)
        if _algo_book_visible(row):
            books.append(row)
    top_rows = []
    try:
        sys.path.insert(0, _DIR_POLY)
        from vote_paper import list_top_books
        for b in list_top_books():
            if not _algo_book_visible(b):
                continue
            kid = str(b.get("id") or "")
            n_slot = len(_mirror_top_rows(kid, with_market=False, current_only=not include_all))
            top_rows.append(_mirror_top_book_row(kid, open_count=n_slot, book=b))
    except Exception:
        top_rows = []
    books = top_rows + books
    _sort_algo_islemler_books(books, "book")
    open_m = _mirror_open_minute(None)
    return jsonify({
        "ok": True,
        "server_time_tr": now.isoformat(timespec="seconds"),
        "open_minute": open_m,
        "slot_open_tr": f"{now.hour:02d}:{open_m:02d}",
        "active_slot": slot,
        "active_slot_a2_05": _mirror_active_slot(now, "a2_05"),
        "count": len(books),
        "sort": _ALGO_FEATURED_SORT,
        "featured": list(_ALGO_FEATURED_KEYS),
        "filter": "all" if include_all else "current_slot",
        "policy": _mirror_policy(),
        "books": books,
    })


@app.route("/poly/api/mirror/<book_id>")
def api_mirror_book(book_id: str):
    """Tek defterin şu anki açık pozisyonları — aynalayarak açmak için yeterli alan."""
    if not _mirror_token_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    key = _normalize_algo_book_id(book_id)
    is_top = _mirror_is_top(key)
    if not is_top and key not in _ALGO_ISLEMLER_KEYS:
        return jsonify({"ok": False, "error": "not found",
                        "hint": "defter listesi: /poly/api/mirror"}), 404
    try:
        _mirror_query_slot()
    except ValueError:
        return jsonify({"ok": False, "error": "slot 02/05/07"}), 400
    with_market = (request.args.get("market") or "1").lower() not in ("0", "false", "no")
    include_all = (request.args.get("all") or "").lower() in ("1", "true", "yes")
    if is_top:
        rows = _mirror_top_rows(key, with_market=with_market, current_only=not include_all)
        info = _mirror_top_book_row(key, open_count=len(rows))
        open_m = 5
    else:
        rows = _mirror_rows(key, with_market=with_market, current_only=not include_all)
        info = _mirror_book_row(key, open_count=len(rows))
        open_m = _mirror_open_minute(key)
    now = datetime.now(_TZ_TR)
    slot = _mirror_active_slot(now, None if is_top else key)
    return jsonify({
        "ok": True,
        **info,
        "server_time_tr": now.isoformat(timespec="seconds"),
        "open_minute": open_m,
        "slot_open_tr": slot.get("slot_open_tr") or f"{now.hour:02d}:{open_m:02d}",
        "active_slot": slot,
        "filter": "all" if include_all else "current_slot",
        "policy": _mirror_policy(),
        "count": len(rows),
        "copyable_count": sum(1 for r in rows if r.get("copyable")),
        "positions": rows,
    })


@app.route("/poly/api/mirror-slot", methods=["GET", "POST"])
def api_mirror_slot():
    """Ayna API hangi açılış dakikasını yayınlar — varsayılan :05, defter bazında."""
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if request.method == "GET":
        cfg = load_mirror_slot_cfg()
        return jsonify({
            "ok": True,
            "default": cfg.get("default", 5),
            "books": cfg.get("books") or {},
            "minutes": list(_SLOT_MINUTES),
        })
    body = request.get_json(silent=True) or {}
    book_raw = (body.get("book") or body.get("book_key") or "").strip()
    raw_slot = body.get("slot", body.get("open_minute"))
    if raw_slot is None:
        return jsonify({"ok": False, "error": "slot gerekli (02/05/07)"}), 400
    try:
        minute = _parse_open_slot(raw_slot)
    except ValueError:
        return jsonify({"ok": False, "error": "slot 02/05/07"}), 400
    if book_raw:
        key = _normalize_algo_book_id(book_raw)
        if key not in _ALGO_ISLEMLER_KEYS:
            return jsonify({"ok": False, "error": "not found"}), 404
        cfg = save_mirror_slot(book=key, slot=minute)
        return jsonify({
            "ok": True,
            "book": key,
            "slot": minute,
            "default": cfg.get("default", 5),
            "books": cfg.get("books") or {},
        })
    cfg = save_mirror_slot(default=minute)
    return jsonify({
        "ok": True,
        "slot": minute,
        "default": cfg.get("default", 5),
        "books": cfg.get("books") or {},
    })


@app.route("/poly/api/analizler")
def api_analizler():
    if _auth_required(): return jsonify({"error": "unauthorized"}), 401
    results = []
    for key, label, init_bal, desc in _ANALIZLER_SYSTEMS:
        if key in _REMOVED_ANALYSES or key in _LIVE_PM_ANALYSES:
            continue
        hpath = _trader_history_path(key)
        spath = _trader_state_path(key)
        if not os.path.exists(hpath) and not os.path.exists(spath):
            continue
        try:
            hist  = _load_trader_history(key) if os.path.exists(hpath) else []
            state = json.load(open(spath, encoding="utf-8")) if os.path.exists(spath) else {}
        except Exception:
            continue
        total = len(hist)
        if total < _ALGO_STATS_MIN_TRADES:
            continue
        wins  = sum(1 for t in hist if t.get("win"))
        wr    = round(wins / total * 100, 1) if total else 0
        bal   = state.get("balance", init_bal or 0)
        pnl   = round(bal - init_bal, 2) if init_bal else round(sum(t.get("pnl", 0) for t in hist), 2)
        allowed = _allowed_syms_for(key)
        open_cnt = len([
            p for p in state.get("open_positions", [])
            if p.get("symbol", "").replace("USDT", "") in allowed
        ])
        if total == 0 and open_cnt == 0 and not os.path.exists(spath):
            continue
        # Sembol bazlı
        sym_stats = {}
        for t in hist:
            sym = t.get("symbol", "").replace("USDT", "")
            if sym not in allowed:
                continue
            if sym not in sym_stats:
                sym_stats[sym] = {"w": 0, "t": 0}
            sym_stats[sym]["t"] += 1
            if t.get("win"):
                sym_stats[sym]["w"] += 1
        sym_list = []
        syms_for = allowed
        for sym in syms_for:
            v = sym_stats.get(sym)
            if v and v["t"]:
                sym_list.append({"sym": sym, "w": v["w"], "t": v["t"],
                                  "wr": round(v["w"]/v["t"]*100, 1)})
        results.append({
            "key": key, "label": label, "desc": desc,
            "init_bal": init_bal, "balance": round(bal, 2),
            "total": total, "wins": wins, "wr": wr, "pnl": pnl,
            "open": open_cnt, "sym_stats": sym_list,
        })
    results.sort(key=lambda x: (x["wr"], x["total"], x["open"]), reverse=True)
    return jsonify(results)


def _load_balance_hourly_records() -> list:
    if not os.path.isfile(_PM_BALANCE_HOURLY_FILE):
        return []
    try:
        with open(_PM_BALANCE_HOURLY_FILE, encoding="utf-8") as f:
            data = json.load(f)
        recs = data.get("records", data if isinstance(data, list) else [])
        return recs if isinstance(recs, list) else []
    except Exception:
        return []


def _balance_record_dt(rec: dict):
    ts = rec.get("time_tr")
    if not ts:
        return None
    try:
        dt = datetime.fromisoformat(ts)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_TZ_TR)
        else:
            dt = dt.astimezone(_TZ_TR)
        return dt
    except (ValueError, TypeError):
        return None


def _aggregate_balance_4h(records: list) -> list:
    buckets: dict[str, dict] = {}
    for r in records:
        dt = _balance_record_dt(r)
        if not dt:
            continue
        bucket_h = (dt.hour // 4) * 4
        key = dt.replace(hour=bucket_h, minute=0, second=0, microsecond=0).isoformat()
        buckets[key] = r
    return [buckets[k] for k in sorted(buckets)]


def _display_book_balance_history_points(interval: str) -> dict:
    """Seçili sanal defter (pm_home_display) portföy eğrisi — gerçek PM hourly değil."""
    key, label, slot, init_bal = _home_display_ctx()
    state = load_state(key, slot)
    hist = _load_trader_history(key, slot)
    reset_at = state.get("balance_reset_at_tr")
    hist_stats = hist
    if reset_at:
        hist_stats = [
            t for t in hist
            if (t.get("exit_time_tr") or "") >= reset_at
        ]

    events: list[tuple[datetime, float]] = []
    start_raw = reset_at
    if not start_raw:
        times = [t.get("exit_time_tr") or t.get("entry_time_tr") for t in hist_stats]
        times = [x for x in times if x]
        if times:
            start_raw = min(times)
    if start_raw:
        try:
            start_dt = datetime.fromisoformat(str(start_raw))
            if start_dt.tzinfo is None:
                start_dt = start_dt.replace(tzinfo=_TZ_TR)
            events.append((start_dt, float(init_bal)))
        except Exception:
            pass

    bal = float(init_bal)
    closed = sorted(
        [
            t for t in hist_stats
            if t.get("win") is not None and t.get("exit_time_tr")
        ],
        key=lambda t: str(t.get("exit_time_tr")),
    )
    for t in closed:
        bal += float(t.get("pnl") or 0)
        try:
            dt = datetime.fromisoformat(str(t["exit_time_tr"]))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=_TZ_TR)
            events.append((dt, round(bal, 2)))
        except Exception:
            continue

    _cash, portfolio = _display_pm_balance()
    now = datetime.now(_TZ_TR)
    port = round(float(portfolio), 2)
    if not events:
        events.append((now, port))
    elif abs(events[-1][1] - port) > 0.009 or (now - events[-1][0]).total_seconds() > 300:
        events.append((now, port))

    if not events:
        return {
            "interval": interval,
            "baseline": init_bal,
            "points": [],
            "current": port,
            "delta": None,
            "display_book": key,
            "display_label": label,
            "display_slot": slot,
            "source": "display_book",
        }

    step_h = 1 if interval == "1h" else 4
    t0 = events[0][0].astimezone(_TZ_TR)
    t1 = now
    bucket = t0.replace(minute=0, second=0, microsecond=0)
    if interval == "4h":
        bucket = bucket.replace(hour=(bucket.hour // 4) * 4)

    points: list[dict] = []
    ev_i = 0
    cur_bal = float(init_bal)
    while bucket <= t1 + timedelta(hours=step_h):
        while ev_i < len(events) and events[ev_i][0] <= bucket:
            cur_bal = float(events[ev_i][1])
            ev_i += 1
        points.append({
            "time": int(bucket.timestamp()),
            "portfolio": round(cur_bal, 2),
            "cash": round(_cash, 2),
            "positions": round(max(0.0, cur_bal - _cash), 2),
            "label": bucket.strftime("%d.%m %H:%M"),
        })
        bucket += timedelta(hours=step_h)

    cur = points[-1]["portfolio"] if points else port
    delta = None
    if len(points) >= 2:
        lookback = 24 if interval == "1h" else 6
        prev = points[max(0, len(points) - lookback - 1)]["portfolio"]
        delta = round(cur - prev, 2)
    return {
        "interval": interval,
        "baseline": init_bal,
        "points": points,
        "current": cur,
        "delta": delta,
        "display_book": key,
        "display_label": label,
        "display_slot": slot,
        "source": "display_book",
    }


def _balance_history_points(interval: str) -> dict:
    return _display_book_balance_history_points(interval)


@app.route("/poly/api/balance-history")
def api_balance_history():
    if _auth_required():
        return jsonify({"error": "unauthorized"}), 401
    interval = request.args.get("interval", "1h")
    if interval not in ("1h", "4h"):
        interval = "1h"
    return jsonify(_balance_history_points(interval))


@app.route("/poly/api/active-algos")
def api_active_algos():
    if _auth_required():
        return jsonify({"error": "unauthorized"}), 401
    from pm_balance_guard import get_pm_system_control
    ctrl = get_pm_system_control()
    recent_n = 14
    results = []
    active_keys = list(dict.fromkeys(_ALGO_ISLEMLER_KEYS + list(_OVERVIEW_ACTIVE_ORDER)))
    for key in active_keys:
        if key in _REMOVED_ANALYSES or key in _LIVE_PM_ANALYSES:
            continue
        hpath = _trader_history_path(key)
        if not os.path.exists(hpath):
            continue
        try:
            hist = _load_trader_history(key)
            spath = _trader_state_path(key)
            state = json.load(open(spath, encoding="utf-8")) if os.path.exists(spath) else {}
        except Exception:
            continue
        init_bal = _OVERVIEW_INIT_BAL.get(key, 300)
        total = len(hist)
        if total < _ALGO_STATS_MIN_TRADES:
            continue
        wins = sum(1 for t in hist if t.get("win"))
        wr = round(wins / total * 100, 1) if total else 0
        bal = round(float(state.get("balance") or 0), 2)
        if init_bal:
            pnl = round(bal - init_bal, 2)
        else:
            pnl = round(sum(t.get("pnl", 0) for t in hist), 2)
        allowed = _allowed_syms_for(key)
        open_cnt = len([
            p for p in state.get("open_positions", [])
            if p.get("symbol", "").replace("USDT", "") in allowed
        ])
        recent = [
            {"win": bool(t.get("win")), "pnl": round(float(t.get("pnl") or 0), 2)}
            for t in hist[-recent_n:]
        ]
        paused = bool(ctrl.get(_PM_PAUSE_KEYS[key])) if key in _PM_PAUSE_KEYS else False
        real_pm = key in _PM_PAUSE_KEYS
        # Gerçek PM state.balance bazen havuz toplamı (210→966); grafikte 300+PnL kullan
        if real_pm:
            if bal and bal <= 450:
                chart_bal = bal
            else:
                chart_bal = round(_OVERVIEW_CHART_BASE + pnl, 2)
        else:
            chart_bal = bal
        results.append({
            "key": key,
            "label": _ANALYSIS_LABELS.get(key, key),
            "short_label": _OVERVIEW_SHORT_LABELS.get(key, _ANALYSIS_LABELS.get(key, key)),
            "init_bal": init_bal,
            "wr": wr,
            "pnl": pnl,
            "balance": bal,
            "chart_balance": chart_bal,
            "total": total,
            "open": open_cnt,
            "recent": recent,
            "paused": paused,
            "real_pm": real_pm,
        })
    results.sort(key=lambda x: float(x.get("chart_balance") or x.get("balance") or 0), reverse=True)
    return jsonify(results[:_ACTIVE_ALGOS_TOP_N])


