_SIDEBAR_PROFIT_JS = """
<script>
window._renderPmProfitTo = function(d, ids) {
  const totalEl = document.getElementById(ids.total);
  const chipsEl = document.getElementById(ids.chips);
  const listEl = document.getElementById(ids.list);
  const svgEl = document.getElementById(ids.svg);
  if (!totalEl || !svgEl) return;
  const total = d.total || 0;
  const items = (d.items || []).slice();
  // Merkez: görseldeki gibi büyük düz sayı
  totalEl.textContent = String(Math.round(Math.abs(total)));
  totalEl.style.color = '#fff';
  totalEl.title = (total >= 0 ? '+' : '-') + '$' + Math.abs(total).toFixed(2);

  // 3 konsantrik radial bar — dış→iç (en büyük |pnl| dışta)
  const ranked = items.slice().sort((a, b) => Math.abs(b.pnl || 0) - Math.abs(a.pnl || 0));
  while (ranked.length < 3) ranked.push({label:'—', pnl:0, color:'#6D5EF7'});
  const top3 = ranked.slice(0, 3);
  const palette = ['#6D5EF7', '#A78BFA', '#F59E0B'];
  const rings = [
    { r: 70, sw: 11 },
    { r: 54, sw: 11 },
    { r: 38, sw: 11 },
  ];
  const cx = 84, cy = 84;
  const track = 'rgba(255,255,255,.08)';
  const maxAbs = Math.max(...top3.map(i => Math.abs(i.pnl || 0)), 1);
  let arcs = '';
  top3.forEach((item, idx) => {
    const { r, sw } = rings[idx];
    const circ = 2 * Math.PI * r;
    const color = item.color || palette[idx];
    const abs = Math.abs(item.pnl || 0);
    // Lider ~88%, diğerleri oransal; 0 ise sadece track
    let pct = abs > 0 ? Math.max(0.12, Math.min(0.88, abs / maxAbs)) : 0;
    const fill = circ * pct;
    const gap = Math.max(0, circ - fill);
    arcs += '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+track+'" stroke-width="'+sw+'"/>';
    if (fill > 0) {
      arcs += '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="'+sw+'"'
        + ' stroke-dasharray="'+fill+' '+gap+'" stroke-linecap="round"'
        + ' transform="rotate(-90 '+cx+' '+cy+')"/>';
    }
  });
  svgEl.setAttribute('viewBox', '0 0 168 168');
  svgEl.innerHTML = arcs;

  // Chip sırası = halka sırası (dış→iç)
  if (chipsEl) {
    chipsEl.innerHTML = top3.map((item, idx) =>
      '<span class="sp-chip"><span class="sp-dot" style="background:'+(item.color||palette[idx])+'"></span>'+(item.label||'—')+'</span>'
    ).join('');
  }
  if (listEl) {
    listEl.innerHTML = items.map(item => {
      const v = item.pnl || 0;
      const vs = (v >= 0 ? '+' : '-') + '$' + Math.abs(v).toFixed(0);
      const vc = v >= 0 ? '#39ff8e' : '#ff5c7a';
      const initials = (item.label || '?').replace(/[^A-Za-z0-9]/g,'').slice(0,2).toUpperCase() || '?';
      const meta = (item.key === 'manual') ? 'Manuel PM' : 'Saatlik gerçek';
      return '<div class="sp-row">'
        + '<div class="sp-avatar" style="background:'+item.color+'">'+initials+'</div>'
        + '<div class="sp-row-main"><div class="sp-row-name">'+item.label+'</div><div class="sp-row-meta">'+meta+'</div></div>'
        + '<div class="sp-row-val" style="color:'+vc+'">'+vs+'</div>'
        + '</div>';
    }).join('');
  }
};
window.renderSidebarProfit = async function() {
  try {
    const r = await fetch('/poly/api/pm-profit', {cache:'no-store'});
    const d = await r.json();
    _renderPmProfitTo(d, {total:'sp-total', chips:'sp-chips', list:'sp-list', svg:'sp-donut'});
    _renderPmProfitTo(d, {total:'sp-mob-total', chips:'sp-mob-chips', list:'sp-mob-list', svg:'sp-mob-donut'});
  } catch(e) { console.error('sidebar profit', e); }
};
if (!window._spBoot) {
  window._spBoot = true;
  document.addEventListener('DOMContentLoaded', () => {
    renderSidebarProfit();
    setInterval(renderSidebarProfit, 60000);
  });
}
</script>"""

_SIDEBAR_PROFIT_BLOCK = _SIDEBAR_PROFIT_HTML + _SIDEBAR_PROFIT_JS


def _patch_sidebar_cleanup(html: str) -> str:
    html = html.replace('  <div class="nav-label">Hesap</div>\n', '')
    html = html.replace('  <a class="nav-item" href="/poly/logout"><span class="nav-dot"></span>Çıkış</a>\n', '')
    return html


def _patch_sidebar_profit(html: str) -> str:
    if _SIDEBAR_PROFIT_BLOCK in html:
        return html
    markers = (
        '  <a class="nav-item" href="/ayarlar"><span class="nav-dot"></span>Ayarlar</a>\n  <div class="sidebar-footer"',
        '  <div class="sidebar-footer"><span class="dot"></span>Canlı</div>',
        '  <div class="sidebar-footer"><span class="live-dot"></span>Canlı</div>',
        '  <div class="sidebar-footer"',
    )
    for marker in markers:
        if marker not in html:
            continue
        if marker.startswith('  <a class="nav-item" href="/ayarlar"'):
            html = html.replace(
                marker,
                '  <a class="nav-item" href="/ayarlar"><span class="nav-dot"></span>Ayarlar</a>\n'
                + _SIDEBAR_PROFIT_BLOCK
                + '\n  <div class="sidebar-footer"',
                1,
            )
        else:
            html = html.replace(marker, _SIDEBAR_PROFIT_BLOCK + '\n  ' + marker, 1)
        break
    if '/* pm-kar-donut */' not in html:
        html = html.replace('</style>', _SIDEBAR_PROFIT_CSS + '\n</style>', 1)
    return html


