_CEMBOT_CLOCK_JS = (
    '<script>(function(){'
    'function tick(){'
    'var els=document.querySelectorAll("[data-cembot-clock]");'
    'if(!els.length)return;'
    'var t="";'
    'try{t=new Date().toLocaleTimeString("tr-TR",{'
    'hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false,'
    'timeZone:"Europe/Istanbul"});}'
    'catch(e){var d=new Date();'
    't=String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0")'
    '+":"+String(d.getSeconds()).padStart(2,"0");}'
    'els.forEach(function(el){el.textContent=t;});'
    '}'
    'tick();setInterval(tick,1000);'
    '})();</script>'
)


def _patch_cembot_brand(html: str) -> str:
    """Sidebar / mobil / login PolyMarket logosunu CemBOT markasına çevir."""
    if not html:
        return html
    if 'class="cembot"' not in html:
        html = html.replace(
            '<div class="logo">Poly<span>Market</span></div>',
            _CEMBOT_BRAND_HTML,
        )
        html = html.replace(
            '<div class="logo">PolyMarket</div>',
            _CEMBOT_BRAND_HTML,
        )
        html = html.replace(
            '<div class="mobile-logo">PolyMarket</div>',
            _CEMBOT_MOBILE_HTML,
        )
    if 'class="cembot"' in html and "/* cembot-brand */" not in html:
        if "</style>" in html:
            html = html.replace("</style>", _CEMBOT_BRAND_CSS + "\n</style>", 1)
        elif "</head>" in html:
            html = html.replace(
                "</head>",
                "<style>" + _CEMBOT_BRAND_CSS + "</style>\n</head>",
                1,
            )
    if "data-cembot-clock" in html and "querySelectorAll(\"[data-cembot-clock]\")" not in html:
        if "</body>" in html:
            html = html.replace("</body>", _CEMBOT_CLOCK_JS + "\n</body>", 1)
        elif "</html>" in html:
            html = html.replace("</html>", _CEMBOT_CLOCK_JS + "\n</html>", 1)
    return html


def _patch_kf_theme(html: str) -> str:
    """Yalnızca Kripto Future (/kripto) sayfasına KF görsel dilini uygula."""
    if not html or "/* kf-theme */" in html:
        return html
    if "family=Sora" not in html:
        if "<style>" in html:
            html = html.replace("<style>", _SORA_FONT_LINKS + "\n<style>", 1)
        elif "</head>" in html:
            html = html.replace("</head>", _SORA_FONT_LINKS + "\n</head>", 1)
    if "</style>" in html:
        html = html.replace("</style>", _KF_THEME_CSS + "\n</style>", 1)
    return html


def _patch_cache_bust(html: str) -> str:
    """Tarayıcı hard refresh istemeden yeni HTML/JS alsın."""
    bust = (
        '<meta http-equiv="Cache-Control" content="no-store, no-cache, must-revalidate"/>'
        '<meta http-equiv="Pragma" content="no-cache"/>'
        f'<script>(function(){{var v="{_DASH_UI_VER}";'
        'try{var k="poly_dash_ui_ver";if(localStorage.getItem(k)!==v){'
        'localStorage.setItem(k,v);'
        'if("caches" in window){caches.keys().then(function(ks){ks.forEach(function(x){caches.delete(x);});});}'
        'location.reload();}}catch(e){}})();</script>'
    )
    if "</head>" in html and "_DASH_UI_VER" not in html and "poly_dash_ui_ver" not in html:
        return html.replace("</head>", bust + "</head>", 1)
    return html


def _patch_nav_islemler(html: str) -> str:
    grafik_link = '<a class="nav-item" href="/poly/grafik"><span class="nav-dot"></span>Grafik</a>\n  '
    islemler_link = '<a class="nav-item" href="/poly/islemler"><span class="nav-dot"></span>İşlemler</a>\n  '
    if 'href="/poly/grafik"' not in html and 'href="/poly/islemler"' in html:
        html = html.replace(
            '<a class="nav-item" href="/poly/islemler"><span class="nav-dot"></span>İşlemler</a>\n',
            islemler_link + grafik_link,
            1,
        )
    if 'href="/poly/islemler"' in html:
        return html
    link_block = islemler_link + grafik_link
    for needle in (
        '<a class="nav-item active" href="/poly/gecmis">',
        '<a class="nav-item" href="/poly/gecmis">',
    ):
        if needle in html:
            return html.replace(needle, link_block + needle, 1)
    return html


def _patch_nav_kripto_future(html: str) -> str:
    """Eski /kripto-future adreslerini /kripto yap. Dünya geçişi üst barda."""
    html = html.replace('href="/poly/kripto-future"', 'href="/kripto"')
    html = html.replace('href="/kripto-future"', 'href="/kripto"')
