ANALIZLER_HTML = """<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Analizler — PolyMarket</title>
<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='8' fill='%2316a34a'/><text x='50%25' y='50%25' font-size='20' text-anchor='middle' dominant-baseline='central' fill='white' font-family='Arial' font-weight='bold'>P</text></svg>">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0a0a0a;color:#e0e0e0;font-family:'Inter',system-ui,sans-serif;min-height:100vh;display:flex}
.sidebar{width:220px;background:#0a0f0a;padding:24px 16px;display:flex;flex-direction:column;gap:4px;flex-shrink:0;position:sticky;top:0;height:100vh;overflow-y:auto}
.logo{font-size:20px;font-weight:800;color:#fff;margin-bottom:20px;letter-spacing:-0.5px}
.logo span{color:#c8f135}
.nav-label{font-size:10px;color:#444;text-transform:uppercase;letter-spacing:1px;padding:12px 12px 4px}
.nav-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:10px;color:#888;text-decoration:none;font-size:14px;transition:.15s}
.nav-item:hover{background:#1a1a1a;color:#fff}
.nav-item.active{background:#1a2e1a;color:#c8f135;font-weight:600}
.nav-dot{width:6px;height:6px;border-radius:50%;background:#333;flex-shrink:0}
.nav-item.active .nav-dot,.nav-item:hover .nav-dot{background:#c8f135}
.sidebar-footer{margin-top:auto;font-size:12px;color:#333;padding:8px 12px;display:flex;align-items:center;gap:6px}
.live-dot{width:6px;height:6px;border-radius:50%;background:#22c55e;animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
.main{flex:1;padding:28px;max-width:1200px}
h1{font-size:22px;font-weight:800;margin-bottom:6px}
.subtitle{font-size:13px;color:#555;margin-bottom:24px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
/* Analiz kartı — WR’ye göre ton (yüksek→yeşil, düşük→kırmızı) */
.az-vio{
  position:relative; overflow:hidden; border-radius:28px; padding:20px 18px 16px;
  color:#fff; border:1px solid rgba(255,255,255,.12);
  transition:transform .15s, box-shadow .15s;
}
.az-vio.wr5{ /* ≥60 */
  background:linear-gradient(145deg,#047857 0%,#10b981 45%,#34d399 100%);
  box-shadow:0 16px 36px rgba(16,185,129,.35);
}
.az-vio.wr4{ /* ≥55 */
  background:linear-gradient(145deg,#0f766e 0%,#14b8a6 45%,#2dd4bf 100%);
  box-shadow:0 16px 36px rgba(20,184,166,.32);
}
.az-vio.wr3{ /* ≥50 */
  background:linear-gradient(145deg,#5b21b6 0%,#7c3aed 42%,#a21caf 100%);
  box-shadow:0 16px 36px rgba(91,33,182,.35);
}
.az-vio.wr2{ /* ≥45 */
  background:linear-gradient(145deg,#b45309 0%,#d97706 45%,#f59e0b 100%);
  box-shadow:0 16px 36px rgba(217,119,6,.35);
}
.az-vio.wr1{ /* <45 */
  background:linear-gradient(145deg,#9f1239 0%,#e11d48 45%,#f43f5e 100%);
  box-shadow:0 16px 36px rgba(225,29,72,.35);
}
.az-vio:hover{ transform:translateY(-2px); filter:brightness(1.04); }
.az-vio::before{
  content:''; position:absolute; width:140px; height:140px; border-radius:50%;
  background:rgba(255,255,255,.12); top:-40px; right:-30px; pointer-events:none;
}
.az-vio::after{
  content:''; position:absolute; width:90px; height:90px; border-radius:50%;
  background:rgba(255,255,255,.08); top:20px; right:20px; pointer-events:none;
}
.az-title{font-size:13px;font-weight:800;letter-spacing:-.2px;position:relative;z-index:1}
.az-desc{font-size:11px;font-weight:600;opacity:.65;margin-top:3px;position:relative;z-index:1}
.az-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px;position:relative;z-index:1}
.az-val{font-size:36px;font-weight:800;letter-spacing:-1.2px;line-height:1}
.az-ico{
  width:42px;height:42px;border-radius:14px;background:rgba(255,255,255,.16);
  display:grid;place-items:center;flex-shrink:0;
}
.az-ico svg{display:block}
.az-meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:14px;position:relative;z-index:1}
.az-meta .k{font-size:10px;font-weight:600;opacity:.7}
.az-meta .v{font-size:13px;font-weight:800;margin-top:3px;white-space:nowrap}
.az-meta .v.pos{color:#39ff8e}
.az-meta .v.neg{color:#ff8fab}
.az-rank{
  position:absolute; top:14px; right:14px; z-index:2;
  font-size:11px; font-weight:800; color:#111; background:rgba(255,255,255,.92);
  border-radius:999px; padding:3px 9px;
}
.az-syms{
  display:grid; grid-template-columns:repeat(3,1fr); gap:8px;
  margin-top:14px; position:relative; z-index:1;
}
.az-syms.cols-1{grid-template-columns:1fr}
.az-syms.cols-2{grid-template-columns:1fr 1fr}
.az-chip{
  text-align:center; padding:10px 6px; border-radius:14px;
  background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.14);
}
.az-chip .n{font-size:12px;color:#fff;font-weight:800;margin-bottom:2px}
.az-chip .p{font-size:15px;font-weight:800;color:#fff;margin-top:4px}
.az-chip .p.ok{color:#39ff8e}
.az-chip .p.mid{color:#fde047}
.az-chip .c{font-size:10px;color:rgba(255,255,255,.7);margin-top:2px}
.az-chip.empty{opacity:.45}
#loading{text-align:center;color:#555;padding:60px;font-size:14px}
</style>
</head>
<body>
<div class="sidebar">
  <div class="logo">Poly<span>Market</span></div>
  <div class="nav-label">Ana Menü</div>
  <a class="nav-item" href="/poly"><span class="nav-dot"></span>Overview</a>
  <a class="nav-item" href="/algoritma"><span class="nav-dot"></span>Algoritma</a>
  <a class="nav-item" href="/poly/harita"><span class="nav-dot"></span>Sıcaklık Haritası</a>
  <a class="nav-item active" href="/analizler"><span class="nav-dot"></span>Analizler</a>
  <a class="nav-item" href="/poly/gecmis"><span class="nav-dot"></span>Geçmiş</a>
  <div class="nav-label">Hesap</div>
  <a class="nav-item" href="/ayarlar"><span class="nav-dot"></span>Ayarlar</a>
  <a class="nav-item" href="/poly/logout"><span class="nav-dot"></span>Çıkış</a>
  <div class="sidebar-footer"><span class="live-dot"></span>Canlı</div>
</div>
<div class="main">
  <h1>Analizler</h1>
  <div class="subtitle" id="subtitle">Yükleniyor…</div>
  <div id="grid" class="grid"><div id="loading">Veriler yükleniyor…</div></div>
</div>
<script>
const AZ_ICO = `<svg width="26" height="26" viewBox="0 0 26 26" fill="none" aria-hidden="true">
  <ellipse cx="13" cy="8" rx="9" ry="3.2" fill="#fff" opacity=".9"/>
  <ellipse cx="13" cy="13" rx="9" ry="3.2" fill="#fff" opacity=".55"/>
  <ellipse cx="13" cy="18" rx="9" ry="3.2" fill="#fff" opacity=".3"/>
</svg>`;

function wrChipCls(wr){ return Number(wr) >= 55 ? 'ok' : 'mid'; }
function wrToneCls(wr){
  const w = Number(wr) || 0;
  if (w >= 60) return 'wr5';
  if (w >= 55) return 'wr4';
  if (w >= 50) return 'wr3';
  if (w >= 45) return 'wr2';
  return 'wr1';
}

async function load(){
  try{
  const r = await fetch('/poly/api/analizler');
  if(!r.ok){ document.getElementById('loading').textContent = 'API hatası: ' + r.status; return; }
  const data = await r.json();
  if(data.error){ document.getElementById('loading').textContent = 'Oturum hatası: ' + data.error; return; }
  document.getElementById('subtitle').textContent =
    `${data.length} sistem · WR’ye göre sıralı · Otomatik güncellenir`;

  const grid = document.getElementById('grid');
  grid.innerHTML = data.map((a, i) => {
    const pnlCls = a.pnl > 0 ? 'pos' : a.pnl < 0 ? 'neg' : '';
    const pnlStr = (a.pnl >= 0 ? '+' : '') + '$' + Math.abs(a.pnl).toFixed(2);
    const balStr = '$' + Number(a.balance).toFixed(2);
    const wrStr  = a.total ? (a.wr + '%') : '—';
    const tone   = wrToneCls(a.total ? a.wr : 0);
    const rank   = i < 3 ? (i + 1) : '';
    const syms = a.sym_stats || [];
    const cols = syms.length >= 3 ? 3 : (syms.length === 2 ? 2 : 1);
    const symHtml = syms.length
      ? syms.map(s => `<div class="az-chip">
          <div class="n">${s.sym}</div>
          <div class="p ${wrChipCls(s.wr)}">${s.wr}%</div>
          <div class="c">${s.w}/${s.t}</div>
        </div>`).join('')
      : `<div class="az-chip empty"><div class="n">—</div><div class="p mid">—</div><div class="c">veri yok</div></div>`;

    return `<div class="az-vio ${tone}">
      ${rank ? `<div class="az-rank">#${rank}</div>` : ''}
      <div class="az-title">${a.label}</div>
      <div class="az-desc">${a.desc || ''}</div>
      <div class="az-top">
        <div class="az-val">${wrStr}</div>
        <div class="az-ico">${AZ_ICO}</div>
      </div>
      <div class="az-meta">
        <div>
          <div class="k">Bakiye</div>
          <div class="v">${balStr}</div>
        </div>
        <div>
          <div class="k">P&amp;L</div>
          <div class="v ${pnlCls}">${pnlStr}</div>
        </div>
        <div>
          <div class="k">İşlem</div>
          <div class="v">${a.wins}/${a.total}${a.open ? ` (+${a.open})` : ''}</div>
        </div>
      </div>
      <div class="az-syms cols-${cols}">${symHtml}</div>
    </div>`;
  }).join('');
  }catch(e){
    document.getElementById('loading').textContent = 'JS hatası: ' + e.message;
    console.error(e);
  }
}

load();
setInterval(load, 60000);
</script>
</body>
</html>"""


GECMIS_HTML = """<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Geçmiş — PolyMarket</title>
<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='8' fill='%2316a34a'/><text x='50%25' y='50%25' font-size='20' text-anchor='middle' dominant-baseline='central' fill='white' font-family='Arial' font-weight='bold'>P</text></svg>">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0a0a0a;color:#e0e0e0;font-family:'Inter',system-ui,sans-serif;min-height:100vh;display:flex}
.sidebar{width:220px;background:#0a0f0a;padding:24px 16px;display:flex;flex-direction:column;gap:4px;flex-shrink:0;position:sticky;top:0;height:100vh;overflow-y:auto}
.logo{font-size:20px;font-weight:800;color:#fff;margin-bottom:20px;letter-spacing:-0.5px}
.logo span{color:#c8f135}
.nav-label{font-size:10px;color:#444;text-transform:uppercase;letter-spacing:1px;padding:12px 12px 4px}
.nav-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:10px;color:#888;text-decoration:none;font-size:14px;transition:.15s}
.nav-item:hover{background:#1a1a1a;color:#fff}
.nav-item.active{background:#1a2e1a;color:#c8f135;font-weight:600}
.nav-dot{width:6px;height:6px;border-radius:50%;background:#333;flex-shrink:0}
.nav-item.active .nav-dot,.nav-item:hover .nav-dot{background:#c8f135}
.sidebar-footer{margin-top:auto;font-size:12px;color:#333;padding:8px 12px;display:flex;align-items:center;gap:6px}
.live-dot{width:6px;height:6px;border-radius:50%;background:#22c55e;animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
.main{flex:1;padding:28px;max-width:1400px}
h1{font-size:22px;font-weight:800;margin-bottom:6px}
.subtitle{font-size:13px;color:#555;margin-bottom:20px}
.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}
.fbtn{background:#111;border:1px solid #2a2a2a;color:#888;font-size:12px;font-weight:600;padding:8px 14px;border-radius:20px;cursor:pointer;transition:.15s}
.fbtn:hover{border-color:#444;color:#ccc}
.fbtn.active{background:#1a2e1a;border-color:#4ade80;color:#4ade80}
.group{margin-bottom:28px}
.group-head{display:flex;align-items:baseline;gap:10px;margin-bottom:10px;flex-wrap:wrap}
.group-title{font-size:16px;font-weight:800}
.group-meta{font-size:12px;color:#555}
.tbl-wrap{background:#111;border:1px solid #1e1e1e;border-radius:14px;overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:13px;min-width:720px}
th{text-align:left;padding:12px 14px;font-size:10px;color:#555;text-transform:uppercase;letter-spacing:.4px;border-bottom:1px solid #1e1e1e;background:#0d0d0d}
td{padding:12px 14px;border-top:1px solid #161616}
tr:hover td{background:#141414}
.sym{font-weight:800;font-size:14px}
.win-yes{color:#4ade80;font-weight:700}
.win-no{color:#f87171;font-weight:700}
.pnl-pos{color:#4ade80;font-weight:700}
.pnl-neg{color:#f87171;font-weight:700}
.empty{color:#555;padding:40px;text-align:center;font-size:14px}
#loading{color:#555;padding:60px;text-align:center}
@media(max-width:800px){.sidebar{display:none}.main{padding:16px}}
</style>
</head>
<body>
<div class="sidebar">
  <div class="logo">Poly<span>Market</span></div>
  <div class="nav-label">Ana Menü</div>
  <a class="nav-item" href="/poly"><span class="nav-dot"></span>Overview</a>
  <a class="nav-item" href="/algoritma"><span class="nav-dot"></span>Algoritma</a>
  <a class="nav-item" href="/poly/harita"><span class="nav-dot"></span>Sıcaklık Haritası</a>
  <a class="nav-item" href="/analizler"><span class="nav-dot"></span>Analizler</a>
  <a class="nav-item active" href="/poly/gecmis"><span class="nav-dot"></span>Geçmiş</a>
  <div class="nav-label">Hesap</div>
  <a class="nav-item" href="/ayarlar"><span class="nav-dot"></span>Ayarlar</a>
  <a class="nav-item" href="/poly/logout"><span class="nav-dot"></span>Çıkış</a>
  <div class="sidebar-footer"><span class="live-dot"></span>Canlı</div>
</div>
<div class="main">
  <h1>📜 Geçmiş İşlemler</h1>
  <div class="subtitle" id="subtitle">Tüm analizlerin son kapanan işlemleri</div>
  <div class="filters" id="filters"></div>
  <div id="content"><div id="loading">Yükleniyor…</div></div>
</div>
<script>
let _filter = 'ALL';
let _data = null;

function tradeRows(trades){
  if(!trades.length) return '<div class="empty">Bu analizde henüz kapanmış işlem yok</div>';
  return `<div class="tbl-wrap"><table>
    <thead><tr>
      <th>Sembol</th><th>Yön</th><th>Sonuç</th><th>Giriş</th><th>Çıkış</th>
      <th>Risk</th><th>P&amp;L</th><th>Tarih</th>
    </tr></thead><tbody>
    ${trades.map(t=>{
      const w = t.win===true?'win-yes':t.win===false?'win-no':'';
      const wTxt = t.win===true?'✅':t.win===false?'❌':'⏳';
      const pnlC = t.pnl>=0?'pnl-pos':'pnl-neg';
      const dir = t.dir==='UP'?'📈 UP':'📉 DOWN';
      const ent = t.entry!=null?t.entry:'—';
      const ext = t.exit!=null?t.exit:'—';
      return `<tr>
        <td class="sym">${t.sym}</td>
        <td>${dir}</td>
        <td class="${w}">${wTxt}</td>
        <td>${ent}</td>
        <td>${ext}</td>
        <td>$${t.spent.toFixed(2)}</td>
        <td class="${pnlC}">${t.pnl>=0?'+':''}$${t.pnl.toFixed(2)}</td>
        <td style="color:#666;font-size:12px">${t.time}</td>
      </tr>`;
    }).join('')}
    </tbody></table></div>`;
}

function render(){
  const el = document.getElementById('content');
  if(!_data || !_data.groups.length){
    el.innerHTML = '<div class="empty">Henüz geçmiş işlem verisi yok</div>';
    return;
  }
  if(_filter === 'ALL'){
    const merged = [..._data.all];
    el.innerHTML = `<div class="group">
      <div class="group-head">
        <div class="group-title">Tüm Analizler</div>
        <div class="group-meta">${merged.length} son işlem (yeniden eskiye)</div>
      </div>
      ${tradeRows(merged)}
    </div>`;
    return;
  }
  const g = _data.groups.find(x=>x.key===_filter);
  if(!g){ el.innerHTML='<div class="empty">Veri yok</div>'; return; }
  el.innerHTML = `<div class="group">
    <div class="group-head">
      <div class="group-title">${g.label}</div>
      <div class="group-meta">${g.trades.length} son işlem · toplam ${g.total} kayıt</div>
    </div>
    ${tradeRows(g.trades)}
  </div>`;
}

function setFilter(key, btn){
  _filter = key;
  document.querySelectorAll('.fbtn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  render();
}

async function load(){
  try{
    const r = await fetch('/poly/api/history?limit=15');
    if(!r.ok) throw new Error('API '+r.status);
    _data = await r.json();
    const filters = document.getElementById('filters');
    const active = [{key:'ALL',label:'Tümü'}].concat(
      _data.groups.map(g=>({key:g.key,label:g.label}))
    );
    filters.innerHTML = active.map((a,i)=>
      `<button class="fbtn${i===0?' active':''}" onclick="setFilter('${a.key}',this)">${a.label}</button>`
    ).join('');
    document.getElementById('subtitle').textContent =
      `${_data.groups.length} analiz · analiz başına son ${_data.limit} işlem`;
    render();
  }catch(e){
    document.getElementById('content').innerHTML =
      '<div class="empty">Yüklenemedi: '+e.message+'</div>';
  }
}

load();
setInterval(load, 60000);
</script>
</body>
</html>"""


@app.route("/poly/gecmis")
@app.route("/poly/gecmis/")
@app.route("/gecmis")
@app.route("/gecmis/")
def page_gecmis():
    if request.path.rstrip("/") == "/gecmis":
        return redirect("/poly/gecmis")
    if _auth_required():
        return _login_redirect()
    return GECMIS_HTML, 200, {"Content-Type": "text/html; charset=utf-8"}


@app.route("/poly/api/stats")
def api_stats():
    if _auth_required(): return redirect("/poly/login")
    analyses = dict(_HISTORY_SYSTEMS)
    algo_stats = []

    for key, label in analyses.items():
        if key in _ALGO_STATS_EXCLUDE:
            continue
        hist = _load_trader_history(key)
        if not hist and not os.path.exists(_trader_history_path(key)):
            continue
        total = len(hist)
        if total < _ALGO_STATS_MIN_TRADES:
            continue
        wins  = sum(1 for t in hist if t.get("win"))
        pnl   = sum(t.get("pnl", 0) for t in hist)
        wr    = round(wins / total * 100, 1) if total else 0
        algo_stats.append({
            "key": key, "label": label,
            "total": total, "wins": wins,
            "wr": wr, "pnl": round(pnl, 2),
        })

    # Son işlemler — anasayfa gösterim defteri (A2#05 sanal, gerçek PM gibi)
    pending, recent = _display_pm_recent_trades(limit=20)

    algo_stats.sort(key=lambda x: x["wr"], reverse=True)
    return jsonify({
        "algo_stats": algo_stats,
        "recent": recent,
        "pending": pending,
        "real_pm": _real_pm_overview_stats(),
    })


@app.route("/poly/api/pm-profit")
def api_pm_profit():
    if _auth_required():
        return redirect("/poly/login")
    return jsonify(get_pm_profit_breakdown())


@app.route("/poly/api/pm-system", methods=["GET"])
def api_pm_system_get():
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    sys.path.insert(0, _DIR_POLY)
    from pm_balance_guard import get_pm_system_control
    return jsonify({"ok": True, **get_pm_system_control()})


@app.route("/poly/api/pm-system", methods=["POST"])
def api_pm_system_post():
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    sys.path.insert(0, _DIR_POLY)
    from pm_balance_guard import (
        is_pm_open_paused,
        set_a3a8_signal_strict,
        set_group_paused,
        set_pm_open_paused,
        toggle_group_paused,
        toggle_pm_open_paused,
    )
    body = request.get_json(force=True) if request.is_json else {}
    if "a3a8_signal_strict" in body:
        state = set_a3a8_signal_strict(bool(body["a3a8_signal_strict"]), source="dashboard")
        return jsonify({"ok": True, **state})
    group = body.get("group")
    # Grup adı geldiyse ASLA ana şaltere düşmemeli: bilinmeyen ad tek defter yerine
    # hepsini çevirirdi. Geçerli grup listesi pm_balance_guard'da tutulur.
    if group == "hourly":
        paused = bool(body["paused"]) if "paused" in body else not is_pm_open_paused()
        state = set_pm_open_paused(paused, source="dashboard")
    elif group is not None:
        try:
            if "paused" in body:
                state = set_group_paused(group, bool(body["paused"]), source="dashboard")
            else:
                state = toggle_group_paused(group, source="dashboard")
        except ValueError as e:
            return jsonify({"ok": False, "error": str(e)}), 400
    elif "paused" in body:
        state = set_pm_open_paused(bool(body["paused"]), source="dashboard")
    else:
        state = toggle_pm_open_paused(source="dashboard")
    return jsonify({"ok": True, **state})


@app.route("/poly/api/pm-transfer", methods=["GET", "POST"])
def api_pm_transfer():
    """Bridge yatır/çek adresleri + isteğe bağlı Relayer gönderim."""
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    sys.path.insert(0, _DIR_POLY)
    try:
        import pm_transfer as pmt
        pmt._load_env()
    except Exception as e:
        return jsonify({"ok": False, "error": f"pm_transfer import: {e}"}), 500

    if request.method == "GET":
        try:
            info = pmt.wallet_info()
            try:
                dep = pmt.bridge_deposit_addresses()
            except Exception as e:
                dep = {"error": str(e)}
            return jsonify({"ok": True, "wallet": info, "deposit": dep})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500

    body = request.get_json(force=True) if request.is_json else {}
    action = str(body.get("action") or "").strip().lower()
    try:
        if action == "deposit":
            return jsonify({"ok": True, "deposit": pmt.bridge_deposit_addresses()})
        if action == "withdraw":
            to = str(body.get("to") or "").strip()
            chain = str(body.get("chain_id") or body.get("chain") or "1")
            token = str(body.get("token") or "USDC")
            if not to:
                return jsonify({"ok": False, "error": "to gerekli"}), 400
            return jsonify({
                "ok": True,
                "withdraw": pmt.bridge_withdraw_addresses(
                    recipient=to, to_chain_id=chain, to_token=token,
                ),
                "note": "Polygon cüzdanından pUSD'yi dönen evm adresine gönderin",
            })
        if action == "status":
            addr = str(body.get("address") or "").strip()
            if not addr:
                return jsonify({"ok": False, "error": "address gerekli"}), 400
            return jsonify({"ok": True, "status": pmt.bridge_status(addr)})
        if action == "send":
            to = str(body.get("to") or "").strip()
            amount = float(body.get("amount") or 0)
            token = str(body.get("token") or "PUSD")
            confirm = bool(body.get("confirm"))
            result = pmt.relay_send_erc20(
                to=to, amount_usd=amount, token=token, confirm=confirm, wait=False,
            )
            code = 200 if result.get("ok") or result.get("dry_run") else 400
            return jsonify({"ok": bool(result.get("ok")), **result}), code
        return jsonify({"ok": False, "error": "action: deposit|withdraw|status|send"}), 400
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 400


def _pm_get_clob_client():
    from pm_trader_helpers import pm_get_client
    return pm_get_client()


def _pm_conditional_shares(token_id: str) -> float:
    """Zincirdeki gerçek conditional token adedi (-1 = okunamadı)."""
    from decimal import Decimal, ROUND_DOWN
    try:
        from py_clob_client_v2.clob_types import BalanceAllowanceParams, AssetType
        client = _pm_get_clob_client()
        bal = client.get_balance_allowance(
            BalanceAllowanceParams(asset_type=AssetType.CONDITIONAL, token_id=token_id)
        )
        raw = int(bal.get("balance", 0))
        return float(Decimal(str(raw / 1_000_000)).quantize(Decimal("0.01"), rounding=ROUND_DOWN))
    except Exception as e:
        print(f"[dashboard] conditional balance: {e}", flush=True)
        return -1.0


_PM_CLOB = "https://clob.polymarket.com"
_PM_BOOK_CACHE: dict[str, dict] = {}
_PM_BOOK_CACHE_TTL = 0.8  # anlık kapatma poll'u için kısa TTL


def _pm_book_bids(book) -> list[dict]:
    """Orderbook bids — dict veya SDK objesi."""
    if book is None:
        return []
    raw = book.get("bids") if isinstance(book, dict) else getattr(book, "bids", None)
    if not raw:
        return []
    out = []
    for b in raw:
        if isinstance(b, dict):
            p, s = b.get("price"), b.get("size")
        else:
            p, s = getattr(b, "price", None), getattr(b, "size", None)
        try:
            pf, sf = float(p), float(s)
        except (TypeError, ValueError):
            continue
        if pf > 0 and sf > 0:
            out.append({"price": pf, "size": sf})
    out.sort(key=lambda x: x["price"], reverse=True)
    return out


def _pm_book_asks(book) -> list[dict]:
    """Orderbook asks — alım için ucuzdan pahalıya."""
    if book is None:
        return []
    raw = book.get("asks") if isinstance(book, dict) else getattr(book, "asks", None)
    if not raw:
        return []
    out = []
    for a in raw:
        if isinstance(a, dict):
            p, s = a.get("price"), a.get("size")
        else:
            p, s = getattr(a, "price", None), getattr(a, "size", None)
        try:
            pf, sf = float(p), float(s)
        except (TypeError, ValueError):
            continue
        if pf > 0 and sf > 0:
            out.append({"price": pf, "size": sf})
    out.sort(key=lambda x: x["price"])
    return out


def _pm_fetch_public_book(token_id: str) -> tuple[str, dict | None]:
    """Public CLOB book. Dönüş: ('ok', book) | ('empty', {}) | ('gone', None) | ('err', None)."""
    if not token_id:
        return "err", None
    tid = str(token_id)
    now = time.time()
    hit = _PM_BOOK_CACHE.get(tid)
    if hit and now - float(hit.get("ts") or 0) < _PM_BOOK_CACHE_TTL:
        return hit["status"], hit.get("book")
    status, book = "err", None
    try:
        url = f"{_PM_CLOB}/book?token_id={urllib.parse.quote(tid, safe='')}"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=2.5) as r:
            book = json.load(r)
        if _pm_book_bids(book) or _pm_book_asks(book):
            status = "ok"
        else:
            status = "empty"
            book = book if isinstance(book, dict) else {}
    except urllib.error.HTTPError as e:
        if e.code in (404, 410):
            status, book = "gone", None
        else:
            status, book = "err", None
    except Exception:
        status, book = "err", None
    _PM_BOOK_CACHE[tid] = {"ts": now, "status": status, "book": book}
    # cache şişmesin
    if len(_PM_BOOK_CACHE) > 80:
        oldest = sorted(_PM_BOOK_CACHE.items(), key=lambda kv: kv[1].get("ts") or 0)[:40]
        for k, _ in oldest:
            _PM_BOOK_CACHE.pop(k, None)
    return status, book


def _pm_ask_buy_avg_price(asks: list[dict], amount_usd: float) -> float | None:
    """$ budget ile ask VWAP (alım fiyatı)."""
    rem = float(amount_usd or 0)
    if rem <= 0 or not asks:
        return None
    got = 0.0
    cost = 0.0
    for a in asks:
        p = float(a["price"])
        avail = float(a["size"])
        if p <= 0 or avail <= 0:
            continue
        take = min(rem / p, avail)
        take = (take * 100) // 1 / 100  # 0.01 floor
        if take < 0.01:
            continue
        c = take * p
        got += take
        cost += c
        rem -= c
        if rem < 0.01:
            break
    if got < 0.01 or cost <= 0:
        return None
    return max(0.02, min(0.98, round(cost / got, 2)))


def _pm_executable_buy_price(token_id: str, amount_usd: float, fallback: float) -> float:
    """Önizleme/açılış — CLOB ask VWAP, yoksa fallback (Gamma)."""
    fb = max(0.02, min(0.98, round(float(fallback or 0.5), 2)))
    if not token_id:
        return fb
    status, book = _pm_fetch_public_book(token_id)
    if status == "ok":
        avg = _pm_ask_buy_avg_price(_pm_book_asks(book), amount_usd)
        if avg is not None:
            return avg
    return fb


def _pm_bid_vwap_proceeds(bids: list[dict], size: float) -> tuple[float, float | None]:
    """Bid derinliğine göre satış getirisi. Bid yoksa (0, 0)."""
    size = float(size or 0)
    if size <= 0:
        return 0.0, None
    if not bids:
        return 0.0, 0.0
    rem = size
    proceeds = 0.0
    for b in bids:
        take = min(rem, float(b["size"]))
        proceeds += take * float(b["price"])
        rem -= take
        if rem <= 1e-9:
            break
    avg = (proceeds / size) if size else 0.0
    return round(proceeds, 2), round(avg, 4)


def _pm_gamma_sell_price(pm_slug: str, token_dir: str) -> float | None:
    """Gamma outcome fiyatı — 0 da geçerli (resolve kaybeden)."""
    if not pm_slug or not token_dir:
        return None
    gp = get_pm_token_price(pm_slug, token_dir)
    if gp is None:
        return None
    gp = float(gp)
    if gp <= 0:
        return 0.0
    if gp >= 1:
        return 0.99
    return max(0.01, min(0.99, round(gp - 0.01, 2)))


def _pm_best_bid(client, token_id: str) -> float | None:
    """Satış için en yüksek bid — önce public book, sonra SDK."""
    status, book = _pm_fetch_public_book(token_id)
    if status == "ok":
        bids = _pm_book_bids(book)
        if bids:
            return float(bids[0]["price"])
    if status in ("empty", "gone"):
        return None
    try:
        book = client.get_order_book(token_id)
        bids = _pm_book_bids(book)
        if bids:
            return float(bids[0]["price"])
    except Exception:
        pass
    return None


def _pm_sell_price(client, token_id: str, size: float, pm_slug: str = "", token_dir: str = "") -> float:
    """Satış fiyatı: orderbook bid → gamma (0 dahil) → market price. Sahte 0.50 yok."""
    from py_clob_client_v2 import OrderType

    status, book = _pm_fetch_public_book(token_id)
    if status == "ok":
        bids = _pm_book_bids(book)
        if bids:
            return max(0.01, min(0.99, round(float(bids[0]["price"]), 2)))
    if status == "empty":
        return 0.0
    if status == "gone":
        gp = _pm_gamma_sell_price(pm_slug, token_dir)
        return 0.0 if gp is None else gp

    bid = _pm_best_bid(client, token_id)
    if bid and bid > 0:
        return max(0.01, min(0.99, round(bid, 2)))

    gp = _pm_gamma_sell_price(pm_slug, token_dir)
    if gp is not None:
        return gp

    try:
        p = float(client.calculate_market_price(token_id, "SELL", size, OrderType.FAK))
        if p > 0:
            return max(0.01, min(0.99, round(p, 2)))
    except Exception:
        pass

    return 0.0


def _pm_sell_ladder_prices(client, token_id: str, size: float, pm_slug: str = "", token_dir: str = "") -> list[float]:
    """FAK satış için azalan fiyat listesi (bid → piyasa → gamma)."""
    from py_clob_client_v2 import OrderType

    candidates: list[float] = []
    bid = _pm_best_bid(client, token_id)
    if bid and bid > 0:
        candidates.append(bid)
    try:
        mp = float(client.calculate_market_price(token_id, "SELL", size, OrderType.FAK))
        if mp > 0:
            candidates.append(mp)
    except Exception:
        pass
    gp = _pm_gamma_sell_price(pm_slug, token_dir)
    if gp is not None and gp > 0:
        candidates.append(gp)

    start = max(candidates) if candidates else 0.01
    start = max(0.01, min(0.99, round(start, 2)))
    prices: list[float] = []
    p = start
    while p >= 0.01 and len(prices) < 20:
        prices.append(round(p, 2))
        p = round(p - 0.03, 2)
    if 0.01 not in prices:
        prices.append(0.01)
    return prices


def _estimate_close_value(pos: dict) -> dict:
    """Anlık kapatma — CLOB bid VWAP; book yoksa Gamma (0 dahil); sahte mid yok."""
    pm_size = float(pos.get("pm_size") or 0)
    pm_spent = float(pos.get("pm_spent") or pos.get("amount") or 0)
    if not pm_size:
        return {"close_val": None, "close_pnl": None, "token_cents": None}
    token_id = pos.get("pm_token_id")
    slug = pos.get("pm_slug", "")
    token_dir = pos.get("pm_token_dir") or pos.get("predicted_dir", "")

    close_val = None
    sell_price = None

    if token_id:
        status, book = _pm_fetch_public_book(token_id)
        if status == "ok":
            bids = _pm_book_bids(book)
            close_val, avg = _pm_bid_vwap_proceeds(bids, pm_size)
            sell_price = avg if avg is not None else 0.0
        elif status == "empty":
            # Bid yok = şu an satılamaz; Gamma mid (ör. 11¢) gerçekçi değil
            close_val, sell_price = 0.0, 0.0
        elif status == "gone":
            # Market kapandı — Gamma resolve (0/1)
            gp = _pm_gamma_sell_price(slug, token_dir)
            if gp is not None:
                sell_price = gp
                close_val = round(pm_size * gp, 2)

    if close_val is None and slug and token_dir:
        gp = _pm_gamma_sell_price(slug, token_dir)
        if gp is not None:
            sell_price = gp
            close_val = round(pm_size * gp, 2)

    # Public book / Gamma yetmezse authenticated CLOB'a düşme —
    # api-key türetemeyince dashboard thread'leri 60 sn kilitleniyordu.

    if close_val is None:
        return {"close_val": None, "close_pnl": None, "token_cents": None}
    return {
        "close_val": round(float(close_val), 2),
        "close_pnl": round(float(close_val) - pm_spent, 2),
        "token_cents": round(float(sell_price or 0) * 100, 1),
    }


def _pm_sell_position(token_id: str, size: float, pm_slug: str = "", token_dir: str = "") -> dict:
    """Polymarket'ta token sat (pozisyonu kapat)."""
    from decimal import Decimal, ROUND_DOWN

    try:
        client = _pm_get_clob_client()
    except Exception as e:
        return {"ok": False, "error": f"client init hatası: {e}"}

    try:
        from py_clob_client_v2 import OrderArgs, OrderType, PartialCreateOrderOptions
        from py_clob_client_v2.order_builder.constants import SELL

        size = float(Decimal(str(size)).quantize(Decimal("0.01"), rounding=ROUND_DOWN))
        if size <= 0:
            return {"ok": False, "error": "geçersiz boyut"}

        last_err = "bilinmeyen hata"
        for price in _pm_sell_ladder_prices(client, token_id, size, pm_slug, token_dir):
            try:
                args = OrderArgs(token_id=token_id, price=price, size=size, side=SELL)
                signed = client.create_order(args, PartialCreateOrderOptions())
                resp = client.post_order(signed, order_type=OrderType.FAK)
                print(f"[dashboard] PM sell @{price}: {resp}", flush=True)
            except Exception as e:
                last_err = str(e)
                continue

            if not resp:
                last_err = "boş yanıt"
                continue

            status = resp.get("status", "")
            if resp.get("success") and status in ("matched", "live", "delayed"):
                try:
                    received = round(float(resp.get("takingAmount") or 0), 2)
                except (TypeError, ValueError):
                    received = round(size * price, 2)
                if received <= 0:
                    received = round(size * price, 2)
                try:
                    sold = round(float(resp.get("makingAmount") or size), 2)
                except (TypeError, ValueError):
                    sold = size
                return {
                    "ok": True, "price": price, "size": sold,
                    "received": received, "status": status,
                }

            last_err = resp.get("errorMsg") or f"FAK eşleşmedi (status={status})"

        sys.path.insert(0, _DIR_POLY)
        from pm_trader_helpers import pm_clob_error_tr
        return {"ok": False, "error": pm_clob_error_tr(last_err)}

    except Exception as e:
        sys.path.insert(0, _DIR_POLY)
        from pm_trader_helpers import pm_clob_error_tr
        return {"ok": False, "error": pm_clob_error_tr(e)}


def _pm_sell_position_retry(
    token_id: str, size: float, pm_slug: str = "", token_dir: str = "",
) -> dict:
    """Zincir bakiyesine göre sat; kısmi dolumda tekrar dene."""
    from decimal import Decimal, ROUND_DOWN

    chain = _pm_conditional_shares(token_id)
    req = float(Decimal(str(size)).quantize(Decimal("0.01"), rounding=ROUND_DOWN))
    if chain >= 0:
        if chain <= 0.01:
            return {
                "ok": True, "received": 0.0, "size": 0.0, "price": 0.0,
                "reconciled": True, "status": "already_closed",
            }
        req = min(req, chain)

    remaining = req
    total_received = 0.0
    last: dict = {"ok": False, "error": "satış başarısız"}
    for _ in range(6):
        if remaining <= 0.01:
            break
        last = _pm_sell_position(token_id, remaining, pm_slug=pm_slug, token_dir=token_dir)
        if not last.get("ok"):
            break
        got = float(last.get("received") or 0)
        sold = float(last.get("size") or remaining)
        total_received += got
        remaining = round(remaining - sold, 2)
        if remaining <= 0.01:
            break

    if total_received > 0 or last.get("reconciled"):
        out = dict(last)
        out["ok"] = True
        out["received"] = round(total_received, 2)
        out["size"] = round(req - remaining, 2)
        return out
    return last


def _pm_fetch_outcome_prices(slug: str) -> tuple[float, float] | None:
    """Gamma outcome fiyatları (UP, DOWN)."""
    if not slug:
        return None
    try:
        req = urllib.request.Request(
            f"https://gamma-api.polymarket.com/events?slug={slug}",
            headers={"User-Agent": "Mozilla/5.0"},
        )
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.load(r)
        if not data:
            return None
        m = data[0].get("markets", [{}])[0]
        raw_op = m.get("outcomePrices")
        op = json.loads(raw_op) if isinstance(raw_op, str) else (raw_op or [])
        if len(op) < 2:
            return None
        return float(op[0]), float(op[1])
    except Exception:
        return None


def _pm_try_worthless_reconcile(pos: dict) -> dict | None:
    """Token ~$0 (karşı taraf kazandı) — satış yok, kayıp olarak kapat."""
    prices = _pm_fetch_outcome_prices(pos.get("pm_slug", ""))
    if not prices:
        return None
    up_p, down_p = prices
    token_dir = (pos.get("pm_token_dir") or pos.get("predicted_dir") or "").upper()
    lost = (token_dir == "UP" and up_p <= 0.05) or (token_dir == "DOWN" and down_p <= 0.05)
    if not lost:
        return None
    return {
        "ok": True,
        "reconciled": True,
        "worthless": True,
        "received": 0.0,
        "size": float(pos.get("pm_size") or 0),
        "price": 0.0,
        "status": "settled_loss",
    }


def _pm_try_settled_reconcile(pos: dict) -> dict | None:
    """Zincirde token yok — PM market çözülmüşse kazanç/kayıp doğru yaz."""
    slug = pos.get("pm_slug") or ""
    if not slug:
        return None
    sys.path.insert(0, _DIR_POLY)
    try:
        from pm_trader_helpers import pm_fetch_resolution
        res = pm_fetch_resolution(slug)
    except Exception:
        return None
    if not res or not res.get("closed"):
        return None
    token_dir = (pos.get("pm_token_dir") or pos.get("predicted_dir") or "").upper()
    up_won = bool(res.get("up_won"))
    win = (token_dir == "UP" and up_won) or (token_dir == "DOWN" and not up_won)
    size = float(pos.get("pm_size") or 0)
    if win:
        return {
            "ok": True,
            "reconciled": True,
            "worthless": False,
            "received": size,
            "size": size,
            "price": 1.0,
            "status": "settled_win",
            "pm_resolved": True,
        }
    return {
        "ok": True,
        "reconciled": True,
        "worthless": True,
        "received": 0.0,
        "size": size,
        "price": 0.0,
        "status": "settled_loss",
        "pm_resolved": True,
    }


def _short_pm_error(err: str) -> str:
    """UI için kısa Türkçe hata."""
    sys.path.insert(0, _DIR_POLY)
    try:
        from pm_trader_helpers import pm_clob_error_tr
        return pm_clob_error_tr(err)
    except Exception:
        s = str(err or "")
        return s[:72] + "…" if len(s) > 72 else (s or "PM satış başarısız")


_PM_TG_LABELS = {
    "analiz5": "A1 LIVE",
    "analiz2_live": "2. ANALİZ LIVE",
    "manual": "MANUEL PM",
}


def _tg_notify_pm_early_close(analiz: str, pos: dict, sell_result: dict) -> None:
    """Dashboard erken PM satışı — PolyAktif kanalına bildirim."""
    if analiz not in _HOURLY_PM_ANALYSES:
        return
    label = _PM_TG_LABELS.get(analiz, analiz.upper())
    try:
        from pm_trader_helpers import tg_send_pm_live, pm_get_balance, pm_tg_stake
    except ImportError:
        return

    sym = pos.get("symbol", "")
    name = sym.replace("USDT", "")
    pred = pos.get("predicted_dir") or pos.get("pm_token_dir", "")
    entry = float(pos.get("entry_price") or 0)
    spent = float(pos.get("pm_spent") or pos.get("amount") or 0)
    received = float(sell_result.get("received") or 0)
    reconciled = bool(sell_result.get("reconciled"))
    worthless = bool(sell_result.get("worthless"))
    if worthless:
        pnl = round(-spent, 2)
        icon = "❌"
        detail = f"token sıfırlandı  net {pnl:.2f}$"
    elif reconciled and received <= 0:
        est = _estimate_close_value(pos)
        est_pnl = est.get("close_pnl")
        if est_pnl is not None and est.get("close_val"):
            pnl = est_pnl
            icon = "✅" if pnl >= 0 else "❌"
            detail = f"zincirde token yok · tahmini ${est['close_val']:.2f}  net {'+' if pnl >= 0 else ''}{pnl:.2f}$"
        else:
            pnl = 0.0
            icon = "ℹ️"
            detail = "zincirde token kalmadı — satış tutarı doğrulanamadı"
    else:
        pnl = round(received - spent, 2)
        icon = "✅" if pnl >= 0 else "❌"
        detail = f"alınan ${received:.2f}  net {'+' if pnl >= 0 else ''}{pnl:.2f}$"
    stake = pm_tg_stake(pos) or f"💵 ${spent:.2f}"
    hour = pos.get("entry_hour_tr")
    slot = f"{int(hour):02d}:00" if hour is not None else "—"
    bal = pm_get_balance()
    bal_line = f"💰 PM Bakiye: ${bal:.2f}" if bal >= 0 else "💰 PM Bakiye: ?"
    sep = "━" * 26
    tg_send_pm_live(
        f"{sep}\n"
        f"⏹ <b>{label} — {slot} Erken Kapatma</b>  🔴 GERÇEK PM\n"
        f"{icon} <b>{name}</b>  {pred}  giriş:{entry:.2f}\n"
        f"   {stake}  {detail}\n"
        f"{bal_line}\n"
        f"{sep}",
        label=label,
    )


_PM_CLOSE_ANALYSES = _HOURLY_PM_ANALYSES | _15M_PM_ANALYSES


def _pm_close_pnl_from_sell(
    pos: dict, sell_result: dict, pre_est: dict | None = None,
) -> float:
    """Erken kapatma net PnL — satış, reconciled tahmin veya worthless."""
    spent = float(pos.get("pm_spent") or pos.get("amount") or 0)
    received = float(sell_result.get("received") or 0)
    if sell_result.get("worthless"):
        return round(-spent, 2)
    if received > 0:
        return round(received - spent, 2)
    if sell_result.get("reconciled"):
        est = pre_est or _estimate_close_value(pos)
        cp = est.get("close_pnl") if est else None
        if cp is not None:
            return round(float(cp), 2)
        cv = est.get("close_val") if est else None
        if cv is not None:
            return round(float(cv) - spent, 2)
        return 0.0
    return round(received - spent, 2)


def _pm_close_pnl_delta(pos: dict, sell_result: dict) -> float:
    return _pm_close_pnl_from_sell(pos, sell_result)


def _record_dashboard_close(analiz: str, pos: dict, sell_result: dict) -> None:
    """Dashboard erken PM satışını history'ye yaz."""
    if analiz not in _PM_CLOSE_ANALYSES:
        return
    now_tr = datetime.now(timezone.utc).astimezone(_TZ_TR)
    sym = pos.get("symbol", "")
    spent = float(pos.get("pm_spent") or pos.get("amount") or 0)
    received = float(sell_result.get("received") or 0)
    reconciled = bool(sell_result.get("reconciled"))
    worthless = bool(sell_result.get("worthless"))
    pre_est = sell_result.get("_pre_est")
    pnl = _pm_close_pnl_from_sell(pos, sell_result, pre_est)
    if worthless:
        win = False
    elif reconciled and received <= 0:
        win = True if pnl > 0 else False if pnl < 0 else None
    else:
        win = pnl > 0
    pred = pos.get("predicted_dir", "") or pos.get("pm_token_dir", "")
    entry = float(pos.get("entry_price") or 0)

    try:
        current = get_price(sym) if sym else entry
    except Exception:
        current = entry

    actual = "UP" if current >= entry else "DOWN"
    history = _load_trader_history(analiz)
    row = {
        "symbol": sym,
        "predicted_dir": pred,
        "actual_dir": actual,
        "binance_actual": actual,
        "win": win,
        "pm_win": None,
        "settle_source": "worthless" if worthless else ("reconciled" if reconciled else "manual_sell"),
        "entry_price": entry,
        "exit_price": current,
        "entry_time_tr": pos.get("entry_time_tr"),
        "entry_hour_tr": pos.get("entry_hour_tr"),
        "entry_dow": pos.get("entry_dow"),
        "entry_is_weekend": pos.get("entry_is_weekend"),
        "score": pos.get("score", 0),
        "amount": pos.get("amount"),
        "pm_spent": pos.get("pm_spent"),
        "pm_size": pos.get("pm_size"),
        "pm_entry_price": pos.get("pm_entry_price"),
        "pm_order_id": pos.get("pm_order_id"),
        "pm_slug": pos.get("pm_slug"),
        "pm_token_dir": pos.get("pm_token_dir"),
        "exit_time_tr": now_tr.isoformat(),
        "pnl": pnl,
        "pm_live": True,
    }
    if analiz in _15M_PM_ANALYSES:
        row["ts_period"] = pos.get("ts_period") or pos.get("ts_5m")
        row["entry_period_min"] = pos.get("entry_period_min")
    history.append(row)
    _save_trader_history(analiz, history)


