def _trade_desk_quotes_for_tf(timeframe: str, *, include_spot: bool = False) -> list[dict]:
    """Tek TF kotasyonları — sık poll için hafif (spot opsiyonel)."""
    from concurrent.futures import ThreadPoolExecutor
    tf = timeframe if timeframe in ("5m", "15m", "1h") else "15m"
    syms = _trade_desk_short_syms(tf)
    fn = {
        "5m": _trade_desk_quote_5m,
        "15m": _trade_desk_quote_15m,
        "1h": _trade_desk_quote_1h,
    }[tf]
    with ThreadPoolExecutor(max_workers=min(4, len(syms))) as pool:
        rows = list(pool.map(lambda s: fn(s, include_spot=include_spot), syms))
    return [q for q in rows if q]


def _pm_buy_plan(amount: float, price: float) -> dict:
    """PM min 5 pay — gerçek harcama tahmini (pm_place_order ile aynı mantık)."""
    from decimal import Decimal, ROUND_DOWN
    sys.path.insert(0, _DIR_POLY)
    from pm_trader_helpers import pm_fit_buy
    price = max(0.02, min(0.98, round(float(price), 2)))
    raw_sz = float(Decimal(str(amount / price)).quantize(Decimal("0.01"), rounding=ROUND_DOWN))
    size, price = pm_fit_buy(max(5.0, raw_sz), price)
    spent = round(size * price, 2)
    min_size, min_p = pm_fit_buy(5.0, price)
    min_amount = round(min_size * min_p, 2)
    return {
        "price": price,
        "size": size,
        "spent": spent,
        "profit": round(size - spent, 2),
        "min_amount": min_amount,
        "allowed": amount + 0.01 >= min_amount,
    }


def _pm_market_prices(pm: dict) -> tuple[float, float]:
    """5m/15m up_price+down_price; saatlik outcome_prices."""
    if pm.get("up_price") is not None and pm.get("down_price") is not None:
        return float(pm["up_price"]), float(pm["down_price"])
    op = pm.get("outcome_prices") or []
    up = float(op[0]) if len(op) >= 1 else 0.5
    down = float(op[1]) if len(op) >= 2 else 0.5
    return up, down


def _trade_desk_resolve_pm(timeframe: str, symbol: str) -> tuple[dict | None, int | None]:
    ts_period = None
    sys.path.insert(0, _DIR_POLY)
    if timeframe == "5m":
        import poly_trader_5m_common as pm_common
        ts_period, _ = _trade_desk_period_5m()
        pm = pm_common._pm_find_5m_market(ts_period, symbol)
    elif timeframe == "15m":
        import poly_trader_5m_common as pm_common
        ts_period, _ = _trade_desk_period_15m()
        pm = pm_common._pm_find_15m_market(ts_period, symbol)
    else:
        from datetime import timedelta
        from pm_trader_helpers import pm_find_market
        now = datetime.now(timezone.utc)
        et_hour = (now - timedelta(hours=4)).hour
        pm = pm_find_market(symbol, et_hour, now)
    return pm, ts_period


def _trade_desk_live_price(token_id: str, amount: float, fallback: float) -> float:
    try:
        sys.path.insert(0, _DIR_POLY)
        from pm_trader_helpers import pm_get_client
        from py_clob_client_v2 import OrderType
        client = pm_get_client()
        price = float(client.calculate_market_price(token_id, "BUY", amount, OrderType.FAK))
        return max(0.02, min(0.98, round(price, 2)))
    except Exception:
        return max(0.02, min(0.98, round(float(fallback), 2)))


def _trade_desk_open(timeframe: str, symbol: str, direction: str, amount: float) -> dict:
    symbol = symbol.upper()
    direction = direction.upper()
    if timeframe not in ("5m", "15m", "1h"):
        return {"ok": False, "error": "timeframe 5m, 15m veya 1h olmalı"}
    if direction not in ("UP", "DOWN"):
        return {"ok": False, "error": "yön UP veya DOWN olmalı"}
    if symbol not in _trade_desk_short_syms(timeframe):
        return {"ok": False, "error": f"{symbol} bu timeframe için desteklenmiyor"}
    if amount < 1 or amount > 500:
        return {"ok": False, "error": "tutar $1–500 arası olmalı"}

    sys.path.insert(0, _DIR_POLY)
    from pm_trader_helpers import pm_place_order, pm_last_order_error

    pm, ts_period = _trade_desk_resolve_pm(timeframe, symbol)
    if not pm or pm.get("closed"):
        return {"ok": False, "error": "PM market bulunamadı veya kapalı"}

    up_p, down_p = _pm_market_prices(pm)
    quote_p = up_p if direction == "UP" else down_p
    token_id = pm["up_token"] if direction == "UP" else pm["down_token"]
    # Canlı ask VWAP — Gamma mid ile to-win şişmesin
    live_p = _pm_executable_buy_price(token_id, amount, quote_p)
    plan = _pm_buy_plan(amount, live_p)
    if not plan["allowed"]:
        return {
            "ok": False,
            "error": (
                f"Polymarket min 5 pay — @{plan['price']:.2f} fiyatta en az ${plan['min_amount']:.2f} gerekir "
                f"(${amount:.2f} ile ~${plan['spent']:.2f} açılır)"
            ),
            "plan": plan,
        }

    order = pm_place_order(
        token_id, amount, pm.get("tick_size", "0.01"), pm.get("neg_risk", False),
        label="MANUEL PM", interactive=True,
    )
    if not order:
        return {"ok": False, "error": pm_last_order_error()}

    try:
        entry_p = _trade_desk_slot_ref(symbol, timeframe, ts_period)
        if entry_p is None:
            entry_p = get_price(symbol)
    except Exception:
        entry_p = 0.0
    now_tr = datetime.now(timezone.utc).astimezone(_TZ_TR)
    pos = {
        "symbol": symbol,
        "predicted_dir": direction,
        "entry_price": entry_p,
        "amount": order["spent"],
        "pm_spent": order["spent"],
        "to_win": order["size"],
        "token_price": order.get("price"),
        "entry_time_tr": now_tr.isoformat(),
        "entry_dow": now_tr.weekday(),
        "entry_hour_tr": now_tr.hour,
        "entry_is_weekend": now_tr.weekday() >= 5,
        "timeframe": timeframe,
        "pm_slug": pm.get("slug", ""),
        "pm_token_dir": direction,
        "pm_token_id": token_id,
        "pm_size": order["size"],
        "pm_entry_price": order.get("price"),
        "pm_order_id": order.get("order_id", ""),
        "manual": True,
    }
    if timeframe == "5m":
        pos["ts_period"] = ts_period
        pos["ts_5m"] = ts_period
        pos["entry_period_min"] = 5
    elif timeframe == "15m":
        pos["ts_period"] = ts_period
        pos["ts_5m"] = ts_period
        pos["entry_period_min"] = 15

    state = load_state("manual")
    state.setdefault("open_positions", [])
    pos_id = _manual_pos_id(pos)
    state["open_positions"] = [
        p for p in state["open_positions"]
        if _manual_pos_id(p) != pos_id
    ]
    state["open_positions"].append(pos)
    save_state("manual", state)
    sys.path.insert(0, _DIR_POLY)
    try:
        from pm_manual_sync import register_manual_order
        register_manual_order(pos)
    except Exception:
        pass
    spent = order["spent"]
    requested = amount
    note = f" (girdiğin ${requested:.2f})" if abs(spent - requested) > 0.02 else ""
    return {
        "ok": True,
        "position": pos,
        "plan": {
            "price": order.get("price"),
            "size": order["size"],
            "spent": spent,
            "profit": round(float(order["size"]) - spent, 2),
        },
        "message": f"{pos['symbol'].replace('USDT', '')} {'YÜKSELİR' if direction == 'UP' else 'DÜŞER'} "
                   f"${spent:.2f} @{order.get('price', 0):.2f} → ${float(order['size']):.2f} to win{note}",
    }


def _clip_chart_overlay(overlay: dict | None, t0: int, t1: int) -> dict | None:
    """Overlay serilerini mum penceresine kırp (fitContent genişlemesini önler)."""
    if not overlay or not overlay.get("ok"):
        return overlay
    ov = overlay.get("overlays") or {}

    def _clip(series):
        if not series:
            return []
        return [p for p in series if t0 <= int(p["time"]) <= t1]

    out = dict(overlay)
    out["overlays"] = {
        **ov,
        "ema_fast": _clip(ov.get("ema_fast")),
        "ema_slow": _clip(ov.get("ema_slow")),
        "composite": _clip(ov.get("composite")),
        "trend": _clip(ov.get("trend")),
    }
    sigs = overlay.get("signals") or []
    out["signals"] = [s for s in sigs if t0 <= int(s["time"]) <= t1]
    return out


def _snap_overlay_signals_to_chart(candles: list[dict], signals: list[dict]) -> list[dict]:
    """110 motor oklarını mum zamanına hizala (1m grafikte 15m sinyaller)."""
    if not candles or not signals:
        return signals or []
    times = [int(c["time"]) for c in candles]
    time_set = set(times)

    def _snap(t: int) -> int | None:
        best = min(times, key=lambda x: abs(x - t))
        return best if abs(best - t) <= 450 else None

    out: list[dict] = []
    seen: set[tuple] = set()
    for s in signals:
        raw_t = int(s["time"])
        st = raw_t if raw_t in time_set else _snap(raw_t)
        if st is None:
            continue
        key = (st, s.get("dir"))
        if key in seen:
            continue
        seen.add(key)
        out.append({**s, "time": st})
    return out


def _candles_through_slot_open(candles: list[dict], window_start: int) -> list[dict]:
    """Slot açılış mumuna kadar (dahil) — tahminler slot boyunca sabit kalır."""
    if not candles:
        return []
    for i, c in enumerate(candles):
        if int(c["time"]) >= window_start:
            return candles[: i + 1]
    return candles


def _algo_overlay_slot_open(overlay: dict, window_start: int) -> dict | None:
    if not overlay or not overlay.get("ok"):
        return None
    comp_s = (overlay.get("overlays") or {}).get("composite") or []
    trend_s = (overlay.get("overlays") or {}).get("trend") or []
    if not comp_s:
        return None
    best_i = -1
    best_t = -1
    for i, pt in enumerate(comp_s):
        t = int(pt["time"])
        if t <= window_start and t >= best_t:
            best_t = t
            best_i = i
    if best_i < 0:
        return None
    comp_val = float(comp_s[best_i]["value"])
    tr_val = float(trend_s[best_i]["value"]) if best_i < len(trend_s) else 0.0
    algo = overlay.get("algo") or "110"
    gate = float((overlay.get("params") or {}).get("gate") or 15.0)
    direction = None
    if algo == "111":
        if comp_val >= gate and tr_val > 0:
            direction = "UP"
        elif comp_val <= -gate and tr_val < 0:
            direction = "DOWN"
    else:
        if comp_val >= gate:
            direction = "UP"
        elif comp_val <= -gate:
            direction = "DOWN"
    up_pct = int(round(max(0.0, min(100.0, abs(comp_val)))))
    if direction == "UP":
        lbl = f"YUKARI {up_pct}%"
    elif direction == "DOWN":
        lbl = f"AŞAĞI {up_pct}%"
    elif comp_val > 0:
        lbl = f"YUKARI {up_pct}%"
    elif comp_val < 0:
        lbl = f"AŞAĞI {up_pct}%"
    else:
        lbl = "NÖTR"
    guide_dir = direction
    if guide_dir is None:
        guide_dir = "UP" if comp_val > 0 else ("DOWN" if comp_val < 0 else None)
    cur = dict(overlay.get("current") or {})
    cur.update({
        "composite": round(comp_val, 1),
        "trend": round(tr_val, 1),
        "direction": direction,
        "guide_dir": guide_dir,
        "label": lbl,
    })
    return cur


def _attach_slot_open_signals(result: dict, candles: list[dict], window_start: int, dec: int) -> None:
    slot_c = _candles_through_slot_open(candles, window_start)
    if len(slot_c) < 55:
        return
    ref = result.get("ref_price")
    try:
        from chart_multi_confirm_signals import compute_multi_confirm_signals
        mc = compute_multi_confirm_signals(slot_c, dec=dec)
        if mc.get("ok") and result.get("multi_confirm"):
            result["multi_confirm"]["slot_open"] = mc.get("current")
    except Exception:
        pass
    try:
        from chart_yon_tahmin_signals import compute_yon_tahmin_signals
        yt = compute_yon_tahmin_signals(slot_c, dec=dec)
        if yt.get("ok") and result.get("yon_tahmin"):
            result["yon_tahmin"]["slot_open"] = yt.get("current")
    except Exception:
        pass
    try:
        from chart_tahmin2_signals import compute_tahmin2_signals
        t2 = compute_tahmin2_signals(slot_c, ref_price=ref, dec=dec)
        if t2.get("ok") and result.get("tahmin2"):
            result["tahmin2"]["slot_open"] = t2.get("current")
            result["tahmin2"]["slot_open_votes"] = t2.get("votes")
    except Exception:
        pass
    ov = result.get("algo_overlay")
    if ov and ov.get("ok"):
        so = _algo_overlay_slot_open(ov, window_start)
        if so:
            ov["slot_open"] = so


