def _supertrend_dir_from_signals(symbol: str) -> str | None:
    """algo_signals.json #3 Supertrend — sembol yönü."""
    sym = (symbol or "").replace("USDT", "").upper()
    path = "/tmp/algo_signals.json"
    if not os.path.isfile(path):
        return None
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        entry = (data.get("signals") or {}).get("3") or {}
        d = entry.get(sym)
        return d if d in ("UP", "DOWN") else None
    except Exception:
        return None


def _slot_analiz_dirs(symbol: str) -> dict:
    """Grafik için A1 / A6 / Supertrend — açık pozisyon, history veya algo sinyali."""
    sym = (symbol or "").replace("USDT", "").upper()
    hour_key = datetime.now(_TZ_TR).strftime("%Y-%m-%dT%H")
    out: dict = {}
    for key, tag in (("analiz1", "a1"), ("analiz6", "a6")):
        label_tag = tag.upper()
        direction = None
        for p in _load_trader_open_positions(key):
            ps = (p.get("symbol") or "").replace("USDT", "").upper()
            if ps == sym:
                direction = p.get("predicted_dir")
                break
        if direction not in ("UP", "DOWN"):
            try:
                hist = _load_trader_history(key) if os.path.exists(_trader_history_path(key)) else []
            except Exception:
                hist = []
            for t in reversed(hist[-120:] if isinstance(hist, list) else []):
                ts = (t.get("symbol") or "").replace("USDT", "").upper()
                if ts != sym:
                    continue
                et = str(t.get("entry_time_tr") or "")
                if et.startswith(hour_key):
                    direction = t.get("predicted_dir")
                    break
        if direction in ("UP", "DOWN"):
            out[tag] = {
                "dir": direction,
                "label": f"{label_tag} {'↑' if direction == 'UP' else '↓'}",
            }
        else:
            out[tag] = {"dir": None, "label": f"{label_tag} —"}
    st = _supertrend_dir_from_signals(sym)
    if st in ("UP", "DOWN"):
        out["st"] = {"dir": st, "label": f"ST {'↑' if st == 'UP' else '↓'}"}
    else:
        out["st"] = {"dir": None, "label": "ST —"}
    return out


def _snap_hourly_signals_to_chart(
    candles: list[dict],
    signals: list[dict],
    hourly_current: dict,
    window_start: int | None,
) -> list[dict]:
    """Saatlik A1/A3/A8 oklarını mum zamanına hizala (LightweightCharts tam eşleşme ister)."""
    if not candles:
        return []
    times = [int(c["time"]) for c in candles]
    time_set = set(times)

    def _snap(t: int) -> int | None:
        best = min(times, key=lambda x: abs(x - t))
        return best if abs(best - t) <= 2700 else None

    out: list[dict] = []
    seen: set[tuple] = set()
    for s in signals:
        raw_t = int(s["time"])
        st = raw_t if raw_t in time_set else _snap(raw_t)
        if st is None:
            continue
        key = (st, s.get("tag"), s.get("dir"))
        if key in seen:
            continue
        seen.add(key)
        out.append({**s, "time": st})

    if window_start and window_start in time_set and hourly_current:
        for tag, hk in (("A1", "a1"),):
            cur = hourly_current.get(hk)
            if not cur or not cur.get("dir"):
                continue
            key = (window_start, tag, cur["dir"])
            if key in seen:
                continue
            seen.add(key)
            out.append({
                "time": window_start,
                "dir": cur["dir"],
                "tag": tag,
                "live": True,
            })
    return out


def _compute_candle_analysis(candles: list[dict]) -> dict:
    """Sonnet/candle_pattern_engine1 — grafik mumları için pattern + seviye + rapor."""
    if not candles or len(candles) < 3:
        return {"ok": False, "error": "yetersiz mum"}
    try:
        if _DIR_SONNET not in sys.path:
            sys.path.insert(0, _DIR_SONNET)
        import importlib
        import numpy as np
        engine_mod = importlib.import_module("candle_pattern_engine1")
        CandleEngine = engine_mod.CandleEngine

        o = np.array([float(c["open"]) for c in candles], dtype=float)
        h = np.array([float(c["high"]) for c in candles], dtype=float)
        l = np.array([float(c["low"]) for c in candles], dtype=float)
        cl = np.array([float(c["close"]) for c in candles], dtype=float)
        engine = CandleEngine(o, h, l, cl)
        result = engine.confluence_score()
        levels = engine.detect_levels()
        all_patterns = engine.detect_patterns()
        active = {k: v for k, v in all_patterns[-1].items() if v != 0}
        recent = []
        lookback = 12
        for i in range(max(0, len(all_patterns) - lookback), len(all_patterns)):
            pats = {k: v for k, v in all_patterns[i].items() if v != 0}
            if pats:
                recent.append({"idx": i, "patterns": pats})

        def _level_json(lv):
            return {
                "price": round(float(lv.price), 6),
                "kind": lv.kind,
                "touches": int(lv.touches),
                "strength": float(lv.strength),
            }

        def _prox_json(prox):
            if not prox:
                return None
            lv, dist = prox
            return {
                "price": round(float(lv.price), 6),
                "strength": float(lv.strength),
                "dist_pct": float(dist),
            }

        report = ""
        if len(candles) >= 5:
            try:
                report = engine.generate_report()
            except Exception:
                report = ""

        return {
            "ok": True,
            "engine": "candle_pattern_engine1",
            "score": float(result.score),
            "pattern": float(result.pattern_component),
            "level": float(result.level_component),
            "trend": float(result.trend_component),
            "explanation": result.explanation,
            "patterns": active,
            "recent_patterns": recent,
            "nearest_support": _prox_json(result.nearest_support),
            "nearest_resistance": _prox_json(result.nearest_resistance),
            "support": [_level_json(lv) for lv in levels["support"][:5]],
            "resistance": [_level_json(lv) for lv in levels["resistance"][:5]],
            "report": report,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _trade_desk_chart(
    symbol: str,
    timeframe: str,
    *,
    algo: str | None = None,
    ema_fast: int = 9,
    ema_slow: int = 21,
    gate: float = 15.0,
    price_tf: str = "1m",
    candle_limit: int | None = None,
) -> dict:
    """İşlemler grafiği — mumlar + slot ref + opsiyonel 110 algo overlay."""
    import time as _time
    name = symbol.replace("USDT", "")
    dec = 1 if name == "BTC" else 2
    spot = _trade_desk_spot(symbol, timeframe)
    if timeframe == "5m":
        ts_period, slot_label = _trade_desk_period_5m()
        window_secs = 300
        limit_1m = 36
        limit_5m = 12
        limit_15m = 24
        limit_1h = 12
    elif timeframe == "15m":
        ts_period, slot_label = _trade_desk_period_15m()
        window_secs = 900
        limit_1m = 90
        limit_5m = 24
        limit_15m = 60
        limit_1h = 24
    else:
        hour_start = datetime.now(_TZ_TR).replace(minute=0, second=0, microsecond=0)
        ts_period = int(hour_start.timestamp())
        slot_label = spot.get("slot_label") or hour_start.strftime("%H:%M")
        window_secs = 3600
        limit_1m = 120
        limit_5m = 24
        limit_15m = 48
        limit_1h = 48
    algo_key = (algo or "off").lower()
    price_tf = price_tf if price_tf in ("1m", "5m", "15m", "1h") else "1m"
    _px_limits = {"1m": limit_1m, "5m": limit_5m, "15m": limit_15m, "1h": limit_1h}
    if candle_limit is not None:
        cap = max(10, min(500, int(candle_limit)))
        _px_limits[price_tf] = cap
    px_limit = _px_limits[price_tf]
    now_f = _time.time()
    cache_key = (
        symbol, timeframe, ts_period, int(now_f) // 60,
        algo_key, ema_fast, ema_slow, round(float(gate), 1), price_tf,
        px_limit,
    )
    cached = _trade_chart_cache.get(cache_key)
    if cached and now_f - cached[0] < _TRADE_CHART_CACHE_TTL:
        out = dict(cached[1])
        out["live_price"] = spot.get("live_price")
        out["ref_price"] = spot.get("ref_price")
        out["now"] = int(now_f)
        out["algo_panel"] = _load_algo_panel_consensus(symbol, timeframe, ts_period)
        try:
            from chart_signal_accuracy import get_signal_wr_bundle
            out["signal_accuracy"] = get_signal_wr_bundle(symbol, timeframe)
        except Exception:
            out["signal_accuracy"] = {}
        if out.get("candles") and spot.get("live_price") is not None:
            last = dict(out["candles"][-1])
            lp = round(float(spot["live_price"]), dec)
            last["close"] = lp
            last["high"] = max(last["high"], lp)
            last["low"] = min(last["low"], lp)
            out["candles"] = out["candles"][:-1] + [last]
        out["candle_analysis"] = _compute_candle_analysis(out.get("candles") or [])
        return out
    candle_interval = price_tf
    candle_limit = px_limit
    raw = get_klines(symbol, candle_interval, limit=candle_limit)
    candles = [
        {
            "time": k["t"] // 1000,
            "open": round(k["o"], dec),
            "high": round(k["h"], dec),
            "low": round(k["l"], dec),
            "close": round(k["c"], dec),
            "volume": round(k["v"], 2),
        }
        for k in raw
    ]
    if candles:
        t0, t1 = candles[0]["time"], candles[-1]["time"]
    else:
        t0 = t1 = 0
    now_sec = int(now_f)
    result = {
        "symbol": symbol,
        "name": name,
        "timeframe": timeframe,
        "price_tf": price_tf,
        "slot_label": slot_label,
        "ts_period": ts_period,
        "window_start": ts_period,
        "window_end": ts_period + window_secs,
        "ref_price": spot.get("ref_price"),
        "live_price": spot.get("live_price"),
        "dec": dec,
        "candles": candles,
        "now": now_sec,
        "algo_overlay": None,
        "hourly_signals": [],
        "hourly_current": {},
        "fifteen_signals": [],
        "fifteen_current": {},
        "multi_confirm": None,
        "yon_tahmin": None,
        "tahmin2": None,
        "algo_panel": _load_algo_panel_consensus(symbol, timeframe, ts_period),
        "analiz_dirs": _slot_analiz_dirs(symbol),
    }
    try:
        from chart_signal_accuracy import get_signal_wr_bundle
        result["signal_accuracy"] = get_signal_wr_bundle(symbol, timeframe)
    except Exception:
        result["signal_accuracy"] = {}
    if algo_key not in ("", "off", "none", "0"):
        try:
            sys.path.insert(0, _DIR_POLY)
            from chart_algo_overlay import compute_algo_overlay
            result["algo_overlay"] = compute_algo_overlay(
                symbol, algo=algo_key, ema_fast=ema_fast, ema_slow=ema_slow, gate=gate,
            )
            if candles:
                clipped = _clip_chart_overlay(result["algo_overlay"], t0, t1)
                if clipped and clipped.get("signals"):
                    clipped = dict(clipped)
                    clipped["signals"] = _snap_overlay_signals_to_chart(candles, clipped["signals"])
                result["algo_overlay"] = clipped
        except Exception as e:
            result["algo_overlay"] = {"ok": False, "error": str(e), "algo": algo_key}
    if candles:
        t0, t1 = candles[0]["time"], candles[-1]["time"]
        try:
            from chart_hourly_signals import compute_hourly_chart_signals
            hs = compute_hourly_chart_signals(symbol, t0, t1)
            if hs.get("ok"):
                hc = hs.get("current") or {}
                hc = {k: v for k, v in hc.items() if k not in ("a3", "a8")}
                raw_signals = [s for s in (hs.get("signals") or []) if s.get("tag") not in ("A3", "A8")]
                snapped = _snap_hourly_signals_to_chart(
                    candles,
                    raw_signals,
                    hc,
                    ts_period,
                )
                result["hourly_signals"] = snapped
                result["hourly_current"] = hc
                # A1 canlı hesap varsa analiz_dirs'e yansıt
                ad = result.get("analiz_dirs") or {}
                if hc.get("a1") and hc["a1"].get("dir") and not (ad.get("a1") or {}).get("dir"):
                    ad["a1"] = {
                        "dir": hc["a1"]["dir"],
                        "label": hc["a1"].get("label") or f"A1 {'↑' if hc['a1']['dir']=='UP' else '↓'}",
                    }
                    result["analiz_dirs"] = ad
            else:
                result["hourly_signals"] = []
                result["hourly_current"] = {}
        except Exception:
            result["hourly_signals"] = []
            result["hourly_current"] = {}
    if candles and timeframe in ("5m", "15m", "1h"):
        t0, t1 = candles[0]["time"], candles[-1]["time"]
        try:
            from chart_multi_confirm_signals import compute_multi_confirm_signals
            result["multi_confirm"] = compute_multi_confirm_signals(candles, dec=dec)
        except Exception as e:
            result["multi_confirm"] = {"ok": False, "error": str(e)}
        try:
            from chart_yon_tahmin_signals import compute_yon_tahmin_signals
            result["yon_tahmin"] = compute_yon_tahmin_signals(candles, dec=dec)
        except Exception as e:
            result["yon_tahmin"] = {"ok": False, "error": str(e)}
        try:
            from chart_tahmin2_signals import compute_tahmin2_signals
            result["tahmin2"] = compute_tahmin2_signals(
                candles, ref_price=result.get("ref_price"), dec=dec,
            )
        except Exception as e:
            result["tahmin2"] = {"ok": False, "error": str(e), "votes": []}
    if candles:
        _attach_slot_open_signals(result, candles, ts_period, dec)
    result["candle_analysis"] = _compute_candle_analysis(candles)
    _trade_chart_cache[cache_key] = (now_f, result)
    if len(_trade_chart_cache) > 48:
        cutoff = now_f - 120
        for k in list(_trade_chart_cache):
            if _trade_chart_cache[k][0] < cutoff:
                del _trade_chart_cache[k]
    return result


_ISLEMLER_NOCACHE = {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
    "Pragma": "no-cache",
    "Expires": "0",
}


def _json_nocache(data, status=200):
    resp = jsonify(data)
    resp.status_code = status
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    return resp


