@app.route("/poly/api/trade-desk")
def api_trade_desk():
    if _auth_required():
        return jsonify({"error": "unauthorized"}), 401
    from concurrent.futures import ThreadPoolExecutor
    t0 = time.time()
    with ThreadPoolExecutor(max_workers=3) as pool:
        f5 = pool.submit(lambda: _trade_desk_quotes_for_tf("5m", include_spot=True))
        f15 = pool.submit(lambda: _trade_desk_quotes_for_tf("15m", include_spot=True))
        f1h = pool.submit(lambda: _trade_desk_quotes_for_tf("1h", include_spot=True))

        def _take(fut):
            left = max(0.2, 8.0 - (time.time() - t0))
            try:
                return fut.result(timeout=left)
            except Exception:
                return []

        q5, q15, q1h = _take(f5), _take(f15), _take(f1h)
    manual = load_state("manual")
    open_pos = []
    for p in manual.get("open_positions", []):
        if not _position_visible("manual", p):
            continue
        tf = _manual_timeframe(p)
        open_pos.append({
            "symbol": p.get("symbol", "").replace("USDT", ""),
            "symbol_full": p.get("symbol", ""),
            "dir": p.get("predicted_dir", ""),
            "dir_tr": "YÜKSELİR" if p.get("predicted_dir") == "UP" else "DÜŞER",
            "timeframe": tf,
            "slot": _position_slot_range(p, "manual"),
            "spent": round(float(p.get("pm_spent") or p.get("amount") or 0), 2),
            "size": p.get("pm_size"),
            "entry_time": (p.get("entry_time_tr") or "")[:16].replace("T", " "),
            "order_id": _manual_pos_id(p),
        })
    return jsonify({
        "cash": round(get_pm_balance(), 2),
        "quotes_5m": q5,
        "quotes_15m": q15,
        "quotes_1h": q1h,
        "open_positions": open_pos,
        "updated": datetime.now(_TZ_TR).strftime("%H:%M:%S"),
    })


