@app.route("/poly/api/kripto/overview")
def api_kripto_overview():
    """Kripto overview — snapshot tabanlı hızlı yükleme (Binance yok)."""
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if _DIR_KRIPTO not in sys.path:
        sys.path.insert(0, _DIR_KRIPTO)
    from virtual_book import read_snapshot  # noqa: WPS433
    snap = read_snapshot("test", max_age=900) or {}
    mod = _load_agustos_runner("Test")
    coin_leaders = snap.get("coin_leaders")
    if not _leaders_have_skill(coin_leaders):
        coin_leaders = mod.compute_coin_leaders()
    top_success = snap.get("top_success")
    if not _leaders_have_skill(top_success):
        top_success = mod.compute_top_success(n=8)
    waiting = snap.get("waiting") or []
    recent_test = mod.compute_recent_test_trades(limit=12)
    recent_live: list[dict] = []
    melez_paper: dict = {"ok": False}
    a139_paper: dict = {"ok": False}
    a139_live: dict = {"ok": False}
    b1_mum_live: dict = {"ok": False}
    try:
        melez_paper = mod.hero_book("melez", with_marks=True, recent_limit=20)
        a139_paper = melez_paper
    except Exception as exc:
        print(f"[kripto overview] melez_paper: {exc}", flush=True)
    try:
        from crypto_futures_b1_mum import status_block as _b1_status  # noqa: WPS433
        b1_mum_live = _b1_status(refresh_price=False)
        recent_live = list(b1_mum_live.get("recent_trades") or [])
    except Exception as exc:
        print(f"[kripto overview] b1_mum_live: {exc}", flush=True)
    try:
        from crypto_futures_a139 import status_block as _a139_status  # noqa: WPS433
        a139_live = _a139_status(refresh_price=False)
        if not recent_live:
            recent_live = list(a139_live.get("recent_trades") or [])
    except Exception as exc:
        print(f"[kripto overview] a139_live: {exc}", flush=True)
        try:
            from crypto_futures_cr6 import load_history as _cr6_hist  # noqa: WPS433
            for t in list(reversed(_cr6_hist() or []))[:8]:
                sym = (t.get("symbol") or "").upper()
                recent_live.append({
                    "symbol": sym,
                    "name": sym.replace("USDT", "") if sym.endswith("USDT") else sym,
                    "side": t.get("side"),
                    "algo": t.get("algo") or t.get("strategy") or "Live",
                    "pnl": round(float(t.get("pnl") or 0), 4),
                    "exit_time_tr": t.get("exit_time_tr") or "",
                })
        except Exception:
            pass
    jarvis_map: list[dict] = []
    jarvis_meta: dict = {}
    try:
        _test_dir = os.path.join(_DIR_KRIPTO, "Test")
        if _test_dir not in sys.path:
            sys.path.insert(0, _test_dir)
        from jarvis_v1 import mapping_display_rows, mapping_summary  # noqa: WPS433

        jarvis_map = mapping_display_rows()
        jarvis_meta = mapping_summary()
    except Exception as exc:
        print(f"[kripto overview] jarvis_v1_map: {exc}", flush=True)
    return jsonify({
        "ok": True,
        "coin_leaders": coin_leaders,
        "top_success": list(top_success)[:8],
        "waiting": waiting,
        "total_balance": snap.get("total_balance"),
        "total_pnl": snap.get("total_pnl"),
        "total_open": snap.get("total_open") or 0,
        "symbols_n": snap.get("symbols_n") or 28,
        "count": snap.get("count"),
        "recent_test_trades": recent_test,
        "recent_live_trades": recent_live,
        "jarvis_v1_map": jarvis_map,
        "jarvis_v1_meta": jarvis_meta,
        "melez_paper": melez_paper,
        "a139_paper": a139_paper,
        "a139_live": a139_live,
        "b1_mum_live": b1_mum_live,
    })


