def _slim_agustos_list(data: dict) -> dict:
    """Liste yanıtından recent_history çıkar — defter × 30 işlem sayfayı şişiriyordu."""
    books = data.get("books")
    if not books:
        return data
    out = dict(data)
    slim = []
    for b in books:
        if isinstance(b, dict) and "recent_history" in b:
            nb = dict(b)
            nb.pop("recent_history", None)
            slim.append(nb)
        else:
            slim.append(b)
    out["books"] = slim
    return out


def _agustos_status_or_snap(rel_dir: str, snap_key: str):
    """Disk snapshot'ı anında dön — istek yolunda tüm defterler kurulmaz."""
    if _DIR_KRIPTO not in sys.path:
        sys.path.insert(0, _DIR_KRIPTO)
    from virtual_book import read_snapshot  # noqa: WPS433
    expected = _expected_agustos_book_count(rel_dir)
    snap = read_snapshot(snap_key, max_age=86400.0)
    if snap is None:
        snap = read_snapshot(snap_key, max_age=1e12)
    if snap is not None:
        keep = _agustos_catalog_uids(rel_dir)
        if keep:
            books = [
                b for b in (snap.get("books") or [])
                if isinstance(b, dict) and (b.get("id") or b.get("uid")) in keep
            ]
            if len(books) != len(snap.get("books") or []):
                snap = dict(snap)
                snap["books"] = books
                snap["count"] = len(books)
        if expected and _snapshot_book_count(snap) < expected:
            snap = dict(snap)
            snap["_stale_snapshot"] = True
            snap["_snapshot_partial"] = True
        return _slim_agustos_list(snap)
    return {
        "ok": True,
        "kind": snap_key,
        "books": [],
        "count": 0,
        "waiting": [],
        "_warming": True,
    }


@app.route("/poly/api/kripto/algoritmalar")
def api_kripto_algoritmalar():
    if _auth_required():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    try:
        detail_id = (request.args.get("detail") or request.args.get("book") or "").strip()
        if detail_id:
            mod = _load_agustos_runner("Algoritmalar")
            book = mod.book_detail(detail_id, recent_limit=80, with_marks=True)
            if book is None:
                return jsonify({"ok": False, "error": "book not found"}), 404
            return jsonify({"ok": True, "book": book})
        data = _agustos_status_or_snap("Algoritmalar", "algoritmalar")
        panel = (request.args.get("panel") or "").strip().lower()
        if panel in ("v2", "algo2", "a2") and isinstance(data, dict) and data.get("ok"):
            books = [b for b in (data.get("books") or []) if (b.get("panel") or "") == "v2"]
            data = dict(data)
            data["books"] = books
            data["count"] = len(books)
            data["count_v2"] = len(books)
            data["count_v1"] = 0
            data["total_balance"] = round(sum(float(b.get("balance") or 0) for b in books), 2)
            data["total_pnl"] = round(sum(float(b.get("total_pnl") or 0) for b in books), 2)
            data["total_open"] = sum(int(b.get("open_count") or 0) for b in books)
            data["panel_filter"] = "v2"
        return jsonify(data)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


